def __post_init__(self) -> None:
    if (self.over_axes is None) == (self.over_count is None):
        raise ValueError(
            "FanOut needs exactly one key source: give `over_axes` (one "
            "child per resolved axis) or `over_count` (one child per index), "
            "not both and not neither"
        )

def lookup(
    spec: CpdSpec, default_constructor: str | None = None
) -> ConstructorEntry:
    """Resolve ``(family, constructor)`` to a ``ConstructorEntry``.

    This is *the* one site of the D17 constructor-identity rule: the effective
    constructor name is ``spec.constructor or default_constructor``, where the
    caller supplies ``default_constructor`` from the node's ``kind``. Both being
    absent is a loud error here (rather than a confusing ``None`` KeyError at
    registry-lookup time), and an effective name that resolves to no registered
    constructor is a loud error too. Every consumer that needs to turn a spec
    plus a kind into an entry goes through this function, so the rule lives in
    exactly one place.
    """
    constructor_name = spec.constructor or default_constructor
    if constructor_name is None:
        raise ValueError(
            f"cannot resolve a constructor for family {spec.family!r}: "
            "spec.constructor is unset and no default (node kind) was supplied"
        )
    try:
        family_table = REGISTRY[spec.family]
    except KeyError:
        raise KeyError(f"unknown CPD family: {spec.family!r}") from None
    try:
        return family_table[constructor_name]
    except KeyError:
        raise KeyError(
            f"unknown constructor {constructor_name!r} in family "
            f"{spec.family!r}; registered: {sorted(family_table)}"
        ) from None

def _clear_registry() -> None:
    """Wipe the global registry. Intended only for tests."""

    REGISTRY.clear()

def add_node(self, meta: NodeMeta) -> None:
    if meta.node_id in self._g:
        raise ValueError(f"node already exists: {meta.node_id}")
    self._g.add_node(meta.node_id, meta=meta)

def add_edge(self, parent: str, child: str) -> None:
    for n in (parent, child):
        if n not in self._g:
            raise KeyError(f"unknown node: {n}")
    self._g.add_edge(parent, child)

def get(self, node_id: str) -> NodeMeta:
    """Retrieve a node by its ID."""
    if node_id not in self._g:
        raise KeyError(node_id)
    return self._g.nodes[node_id]["meta"]

def nodes(self) -> Iterator[NodeMeta]:
    """Iterate through nodes in the graph."""
    for _, data in self._g.nodes(data=True):
        yield data["meta"]

def parents(self, node_id: str) -> tuple[str, ...]:
    """Produce the IDs of the parents of the node with the given ID."""
    return tuple(self._g.predecessors(node_id))

def children(self, node_id: str) -> tuple[str, ...]:
    """Produce the IDs of the children of the node with the given ID."""
    return tuple(self._g.successors(node_id))

def topological_order(self) -> tuple[str, ...]:
    """Topologically order the graph and output all node IDs in that order."""
    return tuple(nx.topological_sort(self._g))

def as_nx(self) -> nx.DiGraph:
    """Provide the DiGraph wrapped by the BayesGraph."""
    return self._g.copy(as_view=True)

def has(self, site: str) -> bool:
    """True iff ``site`` has an intervention registered."""
    return site in self.by_site

def _coerce_str_tuple(value: Any) -> tuple[str, ...] | None:
    """Normalise a unit or aggregation_geo field to a tuple of strings."""
    if value is None:
        return None
    if isinstance(value, tuple):
        return value
    if isinstance(value, str):
        return (value,)
    return tuple(value)

def selector_kwargs(self) -> dict[str, Any]:
    """Build ``StructuredArray`` selector kwargs for this cell."""
    if self.selectors is not None:
        return dict(self.selectors)
    out: dict[str, Any] = {"year": self.year}
    if self.aggregation_geo is not None:
        out["geo_finest"] = self.aggregation_geo
    elif self.unit:
        # Degenerate case: unit is (geo, gender, urban_rural) or similar.
        # Callers with multi-axis latents should supply explicit
        # ``selectors`` until the config layer standardises unit encoding.
        if len(self.unit) == 1:
            out["geo_finest"] = self.unit[0]
    return out

def cells_from_mapping(
    raw: Mapping[str, Any] | tuple[Mapping[str, Any], ...] | None,
) -> tuple[ObservationCell, ...]:
    """Normalise hyperparameter ``cells`` into frozen ``ObservationCell``s.

    Accepts a list or tuple of dicts or ``None`` (empty bundle). Both forms
    occur: the loader emits a ``tuple`` (``ObservationCellBundle.cells``), while a
    config that declares its cells explicitly arrives as a ``list`` (YAML has no
    tuple, and the schema strips ``ruamel`` containers to plain ``list``/``dict``
    -- see ``io/config/schema.py::_plain_hyperparameter``). Raises ``ValueError``
    on missing required keys.
    """
    if raw is None:
        return ()
    if isinstance(raw, (str, bytes, Mapping)) or not isinstance(raw, Sequence):
        raise TypeError(
            f"cells must be a list or tuple of mappings, got {type(raw).__name__}"
        )
    out: list[ObservationCell] = []
    for i, entry in enumerate(raw):
        if not isinstance(entry, Mapping):
            raise TypeError(
                f"cells[{i}] must be a mapping, got {type(entry).__name__}"
            )
        try:
            indicator = entry["indicator"]
            source = entry["source"]
            year = entry["year"]
        except KeyError as exc:
            raise ValueError(
                f"cells[{i}] missing required key {exc.args[0]!r}"
            ) from exc
        unit = _coerce_str_tuple(entry.get("unit", ()))
        agg = _coerce_str_tuple(entry.get("aggregation_geo"))
        selectors = entry.get("selectors")
        out.append(
            ObservationCell(
                indicator=str(indicator),
                source=str(source),
                year=int(year),
                unit=unit or (),
                aggregation_geo=agg,
                selectors=selectors,
            )
        )
    return tuple(out)

def value_for(self, site: str, shape: tuple[int, ...] | None = None) -> Any:
    """Build a ``shape``-shaped array of ``value``.

    Raises when no shape is supplied rather than falling back to a scalar: a
    scalar would broadcast to anything, which is precisely the silent
    wrongness this rule kind was introduced to make impossible.
    """
    if shape is None:
        raise ValueError(
            f"fill rule for site {site!r} needs the site's shape to build a "
            "value; it was asked without one. Resolve fills at the "
            "conditioning point, where the distribution is in hand."
        )
    return jnp.full(shape, self.value)

def mask_for(self, site: str, shape: tuple[int, ...] | None = None) -> Any:
    """``None``: a fill speaks about every cell of the site, by construction."""
    return None

def literal(site: str, value: Any, mask: Any = None) -> Literal:
    """A rule conditioning one ``site`` on ``value`` exactly as given."""
    return Literal(site=site, value=value, mask=mask)

def fill(sites: Iterable[str], value: float) -> Fill:
    """A rule conditioning every site in ``sites`` on ``value``, at each site's shape."""
    return Fill(claimed=frozenset(sites), value=float(value))

def mask_for(self, site: str, shape: tuple[int, ...] | None = None) -> Any | None:
    """Which cells of ``site`` are observed, or ``None`` if all of them are.

    Same first-match-wins precedence as :meth:`value_for`, and resolved from
    the same rule: a mask that came from a different rule than the value it
    gates would be a mask of something else.
    """
    for rule in self.rules:
        if site in rule.sites():
            return rule.mask_for(site, shape)
    return None

def __post_init__(self) -> None:
    if not callable(self.build):
        raise TypeError(f"SiteSpec.build must be callable, got {self.build!r}")
    if not isinstance(self.axes, tuple):
        raise TypeError(
            f"SiteSpec.axes must be a tuple, got {type(self.axes).__name__}"
        )
    for ax in self.axes:
        if not isinstance(ax, AxisMeta):
            raise TypeError(
                f"SiteSpec.axes entries must be AxisMeta, got "
                f"{type(ax).__name__}"
            )
    if not self.params:
        raise ValueError(
            "SiteSpec.params is empty; a site needs at least one parameter "
            "field (parameters are identified by name, not position)"
        )
    shape = self.cell_shape
    for key, value in self.params.items():
        if not isinstance(key, str) or not key:
            raise TypeError(
                f"SiteSpec.params keys must be non-empty strings, got {key!r}"
            )
        # Broadcastability to the cell grid is the whole contract on a
        # parameter field: a scalar prior strength and a per-cell vector of
        # them are both legal, and the bundler broadcasts before flattening.
        try:
            jnp.broadcast_shapes(jnp.shape(jnp.asarray(value)), shape)
        except (ValueError, TypeError) as exc:
            raise ValueError(
                f"SiteSpec parameter {key!r} has shape "
                f"{jnp.shape(jnp.asarray(value))}, which does not broadcast "
                f"to the cell shape {shape} implied by axes "
                f"{tuple(ax.name for ax in self.axes)}"
            ) from exc

@property
def cell_shape(self) -> tuple[int, ...]:
    """The grid the parameters and the drawn values live on.

    Empty ``axes`` -> ``()``, a single scalar cell.
    """
    return tuple(len(ax.levels) for ax in self.axes)

@property
def n_cells(self) -> int:
    """How many individual values this site draws (1 for a scalar site)."""
    total = 1
    for size in self.cell_shape:
        total *= size
    return total

def broadcast_params(self) -> dict[str, "jnp.ndarray"]:
    """``params`` with every field materialized at exactly ``cell_shape``.

    The single place a parameter field is expanded onto the grid, so the
    solo path and the bundled path cannot expand it differently.
    """
    shape = self.cell_shape
    return {
        key: jnp.broadcast_to(jnp.asarray(value), shape)
        for key, value in self.params.items()
    }

def __post_init__(self) -> None:
    if not isinstance(self.name, str) or not self.name:
        raise ValueError(
            f"BasisSpec.name must be a non-empty string, got {self.name!r}"
        )
    if self.family not in _SUPPORTED_BASIS_FAMILIES:
        raise ValueError(
            f"BasisSpec.family must be one of "
            f"{sorted(_SUPPORTED_BASIS_FAMILIES)}, got {self.family!r}"
        )
    for field_name in ("knots", "grid"):
        value = getattr(self, field_name)
        if not isinstance(value, tuple):
            raise TypeError(
                f"BasisSpec.{field_name} must be a tuple (got "
                f"{type(value).__name__}); pass `tuple(...)` if you have "
                "a list"
            )
        if len(value) == 0:
            raise ValueError(f"BasisSpec.{field_name} must be non-empty")
    # Knots are positions on a shared age coordinate; strict monotonicity
    # is what makes the hat intervals (and `searchsorted`) well defined.
    if any(b <= a for a, b in zip(self.knots, self.knots[1:])):
        raise ValueError(
            f"BasisSpec.knots must be strictly increasing, got {self.knots!r}"
        )
    if self.boundary not in _SUPPORTED_BASIS_BOUNDARIES:
        raise ValueError(
            f"BasisSpec.boundary must be one of "
            f"{sorted(_SUPPORTED_BASIS_BOUNDARIES)}, got {self.boundary!r}"
        )

def __post_init__(self) -> None:
    if not isinstance(self.name, str) or not self.name:
        raise ValueError(
            f"AxisMeta.name must be a non-empty string, got {self.name!r}"
        )
    if not isinstance(self.levels, tuple):
        raise TypeError(
            f"AxisMeta.levels must be a tuple (got "
            f"{type(self.levels).__name__}); pass `tuple(...)` if you "
            "have a list"
        )
    if len(self.levels) == 0:
        raise ValueError(f"AxisMeta {self.name!r}: levels must be non-empty")
    if self.kind not in _AXIS_KINDS:
        raise ValueError(
            f"AxisMeta {self.name!r}: kind must be one of "
            f"{sorted(_AXIS_KINDS)}, got {self.kind!r}"
        )
    if self.axis_role is not None and self.axis_role not in _AXIS_ROLES:
        raise ValueError(
            f"AxisMeta {self.name!r}: axis_role must be one of "
            f"{sorted(_AXIS_ROLES)} or None, got {self.axis_role!r}"
        )
    if self.basis is not None:
        if not isinstance(self.basis, BasisSpec):
            raise TypeError(
                f"AxisMeta {self.name!r}: basis must be a BasisSpec or "
                f"None, got {type(self.basis).__name__}"
            )
        # Interpolability rides on an ordinal axis (D19 2026-06-02).
        if self.kind != "ordinal":
            raise ValueError(
                f"AxisMeta {self.name!r}: a basis axis must be "
                f"kind='ordinal', got {self.kind!r}"
            )
        # One coefficient per knot: the densification matrix has one
        # column per coefficient, so the counts must agree.
        if len(self.basis.knots) != len(self.levels):
            raise ValueError(
                f"AxisMeta {self.name!r}: basis has {len(self.basis.knots)} "
                f"knots but the axis has {len(self.levels)} levels; "
                "len(knots) must equal the axis length (one coefficient "
                "per knot)"
            )

def __post_init__(self) -> None:
    if not isinstance(self.consumer_id, str) or not self.consumer_id:
        raise ValueError(
            f"BundleCellLabel.consumer_id must be a non-empty string, got "
            f"{self.consumer_id!r}"
        )
    if not isinstance(self.role, str) or not self.role:
        raise ValueError(
            f"BundleCellLabel.role must be a non-empty string, got "
            f"{self.role!r}"
        )
    if not isinstance(self.entry_axes, tuple) or not self.entry_axes:
        raise ValueError(
            "BundleCellLabel.entry_axes must be a non-empty tuple of AxisMeta"
        )
    if len(self.coords) != len(self.entry_axes):
        raise ValueError(
            f"BundleCellLabel.coords length ({len(self.coords)}) must "
            f"match entry_axes length ({len(self.entry_axes)})"
        )
    # Name and levels are `AxisMeta`'s own invariants; only the coordinate's
    # membership is this label's to check.
    for i, ax in enumerate(self.entry_axes):
        if not isinstance(ax, AxisMeta):
            raise TypeError(
                f"BundleCellLabel.entry_axes[{i}] must be AxisMeta, got "
                f"{type(ax).__name__}"
            )
        if self.coords[i] not in ax.levels:
            raise ValueError(
                f"BundleCellLabel.coords[{i}]={self.coords[i]!r} is not "
                f"in entry_axes[{i}] levels {ax.levels!r}"
            )

def expand_bundle_entry_labels(
    *,
    consumer_id: str,
    role: str,
    entry_axes: tuple[AxisMeta, ...],
) -> tuple[BundleCellLabel, ...]:
    """Expand one prior entry into flat ``BundleCellLabel``s (C-order)."""
    if not entry_axes:
        raise ValueError("expand_bundle_entry_labels: entry_axes must be non-empty")
    # Cartesian product in axis order (last axis varies fastest — C order).
    labels: list[BundleCellLabel] = []

    def _walk(dim: int, coords: list[Any]) -> None:
        if dim == len(entry_axes):
            labels.append(
                BundleCellLabel(
                    consumer_id=consumer_id,
                    role=role,
                    entry_axes=entry_axes,
                    coords=tuple(coords),
                )
            )
            return
        for level in entry_axes[dim].levels:
            coords.append(level)
            _walk(dim + 1, coords)
            coords.pop()

    _walk(0, [])
    return tuple(labels)

def _walk(dim: int, coords: list[Any]) -> None:
    if dim == len(entry_axes):
        labels.append(
            BundleCellLabel(
                consumer_id=consumer_id,
                role=role,
                entry_axes=entry_axes,
                coords=tuple(coords),
            )
        )
        return
    for level in entry_axes[dim].levels:
        coords.append(level)
        _walk(dim + 1, coords)
        coords.pop()

def __post_init__(self) -> None:
    if not isinstance(self.indicator, str) or not self.indicator:
        raise ValueError(
            f"IndicatorMeta.indicator must be a non-empty string, got "
            f"{self.indicator!r}"
        )
    if self.family not in _INDICATOR_FAMILIES:
        # TODO: extend `_INDICATOR_FAMILIES` and `_reduce`'s dispatch
        # together when a new family (price-level, index, ratio, ...)
        # gets pinned. Until then this guard turns an unknown family
        # into a clear construction-time error.
        raise ValueError(
            f"IndicatorMeta.family must be one of "
            f"{sorted(_INDICATOR_FAMILIES)}, got {self.family!r}"
        )
    if not isinstance(self.unit, str):
        raise TypeError(
            f"IndicatorMeta.unit must be a string, got "
            f"{type(self.unit).__name__}"
        )

def __post_init__(self) -> None:
    if not isinstance(self.axes, tuple):
        raise TypeError(
            f"StructuredArray.axes must be a tuple (got "
            f"{type(self.axes).__name__})"
        )
    if not all(isinstance(a, AxisMeta) for a in self.axes):
        raise TypeError(
            "StructuredArray.axes must contain only AxisMeta instances"
        )
    if not isinstance(self.indicator, IndicatorMeta):
        raise TypeError(
            f"StructuredArray.indicator must be an IndicatorMeta, got "
            f"{type(self.indicator).__name__}"
        )
    if self.population is not None and not isinstance(
        self.population, StructuredArray
    ):
        raise TypeError(
            "StructuredArray.population must be a StructuredArray or "
            f"None, got {type(self.population).__name__}"
        )
    if self.node_id is not None and (
        not isinstance(self.node_id, str) or not self.node_id
    ):
        raise TypeError(
            "StructuredArray.node_id must be a non-empty str or None, got "
            f"{self.node_id!r}"
        )

    # Shape <-> axes consistency. `hasattr(array, 'shape')` lets us be
    # permissive about whether callers pass `jax.Array`, `np.ndarray`,
    # or anything else array-like; the only contract we enforce here
    # is that `.shape` agrees with `axes`.
    if not hasattr(self.array, "shape") or not hasattr(self.array, "ndim"):
        raise TypeError(
            "StructuredArray.array must expose `.shape` and `.ndim` "
            "(got a non-array-like value)"
        )
    if self.array.ndim != len(self.axes):
        raise ValueError(
            f"StructuredArray: array.ndim ({self.array.ndim}) does not "
            f"match len(axes) ({len(self.axes)})"
        )
    for i, axis in enumerate(self.axes):
        if self.array.shape[i] != len(axis.levels):
            raise ValueError(
                f"StructuredArray: axis {axis.name!r} has "
                f"{len(axis.levels)} levels but array.shape[{i}] is "
                f"{self.array.shape[i]}"
            )

    # Axis names unique. Selectors are keyed by name, so duplicates
    # would be silently shadowed.
    names = [a.name for a in self.axes]
    if len(set(names)) != len(names):
        seen: set[str] = set()
        dupes = [n for n in names if n in seen or seen.add(n)]  # type: ignore[func-returns-value]
        raise ValueError(
            f"StructuredArray: axis names must be unique; duplicates: "
            f"{sorted(set(dupes))}"
        )

@property
def axis_names(self) -> tuple[str, ...]:
    """Tuple of axis names in array order."""
    return tuple(a.name for a in self.axes)

@property
def shape(self) -> tuple[int, ...]:
    """Shorthand for ``self.array.shape``."""
    return tuple(self.array.shape)

def with_node_id(self, node_id: str | None) -> "StructuredArray":
    """This value, attributed to (or detached from) a producing node.

    The stamping seam. ``node_id=None`` detaches, which is what bundle
    projection wants: a ``(consumer, role)`` block is not a node's output.
    """
    return replace(self, node_id=node_id)

def _bundle_axis_or_raise(self, *, caller: str) -> "AxisMeta":
    """Validate this is a 1-D flat ``_bundle`` array; return its axis."""
    if self.array.ndim != 1 or len(self.axes) != 1:
        raise ValueError(
            f"StructuredArray.{caller} expects a 1-D flat bundle "
            f"(ndim={self.array.ndim}, n_axes={len(self.axes)})"
        )
    bundle_axis = self.axes[0]
    if bundle_axis.name != BUNDLE_AXIS_NAME:
        raise ValueError(
            f"StructuredArray.{caller} expects axis {BUNDLE_AXIS_NAME!r}, "
            f"got {bundle_axis.name!r}"
        )
    if not all(isinstance(lv, BundleCellLabel) for lv in bundle_axis.levels):
        raise TypeError(
            f"StructuredArray.{caller}: every _bundle level must be a "
            "BundleCellLabel"
        )
    return bundle_axis

def unbundle_all(
    self, *, consumer_id: str, role: str
) -> tuple["StructuredArray", ...]:
    """Recover **every** entry for one (consumer_id, role) as separate atoms.

    A coalesced effect group holds one entry per demographic axis under the
    same (consumer_id, role) key. This returns them as a tuple of
    single-entry ``StructuredArray``\\ s (one per distinct ``entry_axes``),
    ordered by first appearance on the ``_bundle`` axis. Recovery only — the
    caller (effect-group summation locus) owns broadcasting and summing.
    """
    bundle_axis = self._bundle_axis_or_raise(caller="unbundle_all")
    selected: list[tuple[int, BundleCellLabel]] = [
        (i, lv)
        for i, lv in enumerate(bundle_axis.levels)
        if lv.consumer_id == consumer_id and lv.role == role
    ]
    if not selected:
        raise KeyError(
            f"unbundle_all: no cells for consumer_id={consumer_id!r}, "
            f"role={role!r}"
        )

    # Group by entry_axes, preserving first-appearance order. Two same-named,
    # same-levelled axes differing only in `kind` (or `basis`) are distinct
    # keys here, because the key is now the whole axis.
    groups: dict[tuple[AxisMeta, ...], list[tuple[int, BundleCellLabel]]] = {}
    for i, lv in selected:
        groups.setdefault(lv.entry_axes, []).append((i, lv))

    return tuple(
        self._gather_entry(
            consumer_id=consumer_id,
            role=role,
            entry_axes=entry_axes,
            selected=cells,
            caller="unbundle_all",
        )
        for entry_axes, cells in groups.items()
    )

def _reduced_population(
    self,
    per_axis: list[tuple[list[int] | None, bool]],
    reduce_axis_tuple: tuple[int, ...],
) -> "StructuredArray | None":
    """Build the result's population pointer.

    The pointer is the source population, sliced to the same cells
    as ``self`` and summed over the same axes -- so chained reductions
    keep referring to consistent population totals.
    """
    pop = self.population
    if pop is None:
        return None
    if pop.axes != self.axes:
        if not _population_axes_cover_indicator(pop.axes, self.axes):
            # A widened axis that is being reduced over would have its
            # population counted once per level, so the pointer would come
            # out inflated. No pointer beats a wrong one; the weighted path
            # refuses the same case outright (see `_weight_subset`).
            widened = _widen_weights_to_axes(pop, self.axes)
            if widened is None or (
                _widened_axis_names(pop, self.axes)
                & {self.axes[i].name for i in reduce_axis_tuple}
            ):
                return None
            pop_array = widened
            pop_axes = self.axes
        else:
            pop_array = _align_array_to_axes(pop.array, pop.axes, self.axes)
            pop_axes = self.axes
    else:
        pop_array = pop.array
        pop_axes = pop.axes

    pop_subset_array, pop_subset_axes = _apply_selectors(
        pop_array, pop_axes, per_axis
    )
    new_pop_array = jnp.sum(pop_subset_array, axis=reduce_axis_tuple)
    new_pop_axes = tuple(
        ax for i, ax in enumerate(pop_subset_axes) if i not in set(reduce_axis_tuple)
    )
    return StructuredArray(
        array=new_pop_array,
        axes=new_pop_axes,
        indicator=pop.indicator,
        population=None,
    )

def _population_axes_cover_indicator(
    pop_axes: tuple[AxisMeta, ...],
    indicator_axes: tuple[AxisMeta, ...],
) -> bool:
    """True when population carries every indicator axis name in the same order."""
    if len(indicator_axes) != len(pop_axes):
        return False
    return all(ia.name == pa.name for ia, pa in zip(indicator_axes, pop_axes))

def _widen_weights_to_axes(
    pop: "StructuredArray",
    target_axes: tuple[AxisMeta, ...],
) -> jax.Array | None:
    """The weights' array broadcast onto ``target_axes``, or ``None`` if it can't be.

    An axis the indicator has and the weights lack is answerable: the weights
    do not distinguish its levels, so the same numbers stand for every one of
    them. A segmentation is the case that motivates it -- the share of people in
    each segment divides by the people in the whole cell, not by some
    per-segment population, so one population serves every segment.

    ``None`` when the weights carry an axis the indicator does not, which is the
    other direction and still deferred: collapsing weights down to a coarser
    grid is a reduction, and which reduction depends on the weights' own family.

    Note what this does *not* license: reducing over a widened axis. That is the
    caller's to refuse, because only the caller knows which axes it is reducing
    (see ``_weight_subset``).
    """
    target_names = [axis.name for axis in target_axes]
    if any(axis.name not in target_names for axis in pop.axes):
        return None

    # Align on the shared axes first, at the indicator's order and levels, so
    # ragged coverage is reindexed before anything is widened.
    shared_axes = tuple(
        axis for axis in target_axes if axis.name in {a.name for a in pop.axes}
    )
    pop_by_name = {axis.name: (i, axis) for i, axis in enumerate(pop.axes)}
    order = [pop_by_name[axis.name][0] for axis in shared_axes]
    array = pop.array
    if order != list(range(len(pop.axes))):
        array = jnp.transpose(array, order)
    array = _align_array_to_axes(
        array, tuple(pop_by_name[axis.name][1] for axis in shared_axes), shared_axes
    )

    for position, axis in enumerate(target_axes):
        if axis.name not in pop_by_name:
            array = jnp.expand_dims(array, position)
    return jnp.broadcast_to(
        array, tuple(len(axis.levels) for axis in target_axes)
    )

def _widened_axis_names(
    pop: "StructuredArray",
    target_axes: tuple[AxisMeta, ...],
) -> frozenset[str]:
    """The ``target_axes`` names the weights do not carry."""
    carried = {axis.name for axis in pop.axes}
    return frozenset(axis.name for axis in target_axes if axis.name not in carried)

def _align_array_to_axes(
    array: jax.Array,
    source_axes: tuple[AxisMeta, ...],
    target_axes: tuple[AxisMeta, ...],
) -> jax.Array:
    """Reindex ``array`` onto ``target_axes`` levels (by axis name).

    ``source_axes`` and ``target_axes`` must carry the same axis names in the
    same order. Target levels select a subset (or reorder) of source levels;
    levels absent from the source become ``nan`` (the loader's sparsity convention).
    """
    if source_axes == target_axes:
        return array

    src_by_name = {axis.name: (i, axis) for i, axis in enumerate(source_axes)}
    if not _population_axes_cover_indicator(source_axes, target_axes):
        raise ValueError(
            f"cannot align population axes {[a.name for a in source_axes]} to "
            f"indicator axes {[a.name for a in target_axes]}: names/order differ"
        )

    out = array
    src_order = [src_by_name[axis.name][0] for axis in target_axes]
    if src_order != list(range(len(source_axes))):
        out = jnp.transpose(out, src_order)

    src_levels_in_order = [src_by_name[axis.name][1].levels for axis in target_axes]
    for dim, (src_levels, tgt_axis) in enumerate(
        zip(src_levels_in_order, target_axes)
    ):
        if src_levels == tgt_axis.levels:
            continue
        out = _reindex_levels_along_axis(out, dim, src_levels, tgt_axis.levels)
    return out

def _reindex_levels_along_axis(
    array: jax.Array,
    axis: int,
    source_levels: tuple[Any, ...],
    target_levels: tuple[Any, ...],
) -> jax.Array:
    """Gather ``array`` along ``axis`` onto ``target_levels``; missing -> ``nan``."""
    level_to_idx = {level: i for i, level in enumerate(source_levels)}
    pieces: list[jax.Array] = []
    for level in target_levels:
        src_i = level_to_idx.get(level)
        if src_i is None:
            pieces.append(
                jnp.full(
                    tuple(s for i, s in enumerate(array.shape) if i != axis),
                    jnp.nan,
                    dtype=array.dtype,
                )
            )
        else:
            idx = [slice(None)] * array.ndim
            idx[axis] = src_i
            pieces.append(array[tuple(idx)])
    return jnp.stack(pieces, axis=axis)

def _resolve_selectors(
    axes: tuple[AxisMeta, ...],
    selectors: dict[str, Any],
) -> list[tuple[list[int] | None, bool]]:
    """Turn selector kwargs into a per-axis ``(indices, collapse)`` list.

    Returns one entry per axis (in axis order). ``indices=None`` means
    "no selector touched this axis; keep the full range." ``collapse``
    is ``True`` iff the selector was a scalar (single-value form); the
    axis is then removed from the result's axis list.
    """
    axes_by_name = {a.name: a for a in axes}

    direct: dict[str, Any] = {}  # axis_name -> value (scalar or iterable)
    min_max: dict[str, dict[str, Any]] = {}  # axis_name -> {"min": v, "max": v}

    for key, value in selectors.items():
        if key.startswith("min_") or key.startswith("max_"):
            prefix, sep, name = key.partition("_")
            if not sep or not name:
                raise ValueError(
                    f"selector {key!r}: malformed min_/max_ form (expected "
                    "`min_<axis>` or `max_<axis>`)"
                )
            if name not in axes_by_name:
                raise ValueError(
                    f"selector {key!r}: axis {name!r} is not on this "
                    f"StructuredArray; valid axes: {sorted(axes_by_name)}"
                )
            axis = axes_by_name[name]
            if axis.kind != "ordinal":
                raise ValueError(
                    f"selector {key!r}: range sugar (`min_`/`max_`) is only "
                    f"allowed on ordinal axes; {name!r} is categorical"
                )
            entry = min_max.setdefault(name, {})
            entry[prefix] = value
        else:
            if key not in axes_by_name:
                raise ValueError(
                    f"selector {key!r} is not an axis of this "
                    f"StructuredArray; valid axes: {sorted(axes_by_name)}"
                )
            direct[key] = value

    # Reject mixing forms on the same axis.
    for name in direct:
        if name in min_max:
            raise ValueError(
                f"axis {name!r}: cannot mix direct selector `{name}=` with "
                f"range sugar `min_{name}` / `max_{name}` in the same call"
            )

    per_axis: list[tuple[list[int] | None, bool]] = []
    for axis in axes:
        if axis.name in direct:
            per_axis.append(_indices_for_direct(axis, direct[axis.name]))
        elif axis.name in min_max:
            bounds = min_max[axis.name]
            per_axis.append(
                _indices_for_range(
                    axis,
                    bounds.get("min"),
                    bounds.get("max"),
                )
            )
        else:
            per_axis.append((None, False))
    return per_axis

def _indices_for_direct(
    axis: AxisMeta, value: Any
) -> tuple[list[int], bool]:
    """Resolve a direct selector (scalar or iterable) into indices on ``axis``.

    Scalars collapse the axis (return ``collapse=True``); iterables keep
    it as a (possibly length-1) axis.
    """
    if _is_collection(value):
        levels_to_idx = {lvl: i for i, lvl in enumerate(axis.levels)}
        indices: list[int] = []
        unknown: list[Any] = []
        for v in value:
            if v in levels_to_idx:
                indices.append(levels_to_idx[v])
            else:
                unknown.append(v)
        if unknown:
            raise ValueError(
                f"axis {axis.name!r}: values {unknown!r} not found in axis "
                f"levels {list(axis.levels)!r}"
            )
        if not indices:
            raise ValueError(
                f"axis {axis.name!r}: iterable selector matched zero "
                "levels; pass at least one value"
            )
        return indices, False

    # Scalar form.
    try:
        idx = axis.levels.index(value)
    except ValueError:
        raise ValueError(
            f"axis {axis.name!r}: value {value!r} not found in axis levels "
            f"{list(axis.levels)!r}"
        ) from None
    return [idx], True

def _densify_along_axis(
    array: jax.Array, matrix: jax.Array, axis: int
) -> jax.Array:
    """Apply ``dense = B @ coeffs`` along ``axis`` of ``array``.

    ``matrix`` is ``(n_grid, n_knots)``; ``array``'s ``axis`` dimension has
    length ``n_knots`` and becomes length ``n_grid``, staying in place.
    """
    moved = jnp.moveaxis(array, axis, -1)  # (..., n_knots)
    dense = moved @ matrix.T  # (..., n_grid)
    return jnp.moveaxis(dense, -1, axis)

def _apply_selectors(
    array: jax.Array,
    axes: tuple[AxisMeta, ...],
    per_axis: list[tuple[list[int] | None, bool]],
) -> tuple[jax.Array, tuple[AxisMeta, ...]]:
    """Apply a per-axis selector list, returning the subset array and axes.

    Two-pass design: take along each selected axis first (preserving rank
    so subsequent axis indices stay valid), then squeeze the scalar-
    collapsed axes at the end (in reverse order so earlier squeezes don't
    shift later positions).
    """
    out_array = array
    for i, (indices, _) in enumerate(per_axis):
        if indices is not None:
            out_array = jnp.take(out_array, jnp.asarray(indices), axis=i)
    # Squeeze scalar-collapsed axes in reverse-index order. We're squeezing
    # length-1 dims that we just created via take([idx]), so jnp.squeeze
    # is unambiguous.
    for i in range(len(per_axis) - 1, -1, -1):
        if per_axis[i][1]:
            out_array = jnp.squeeze(out_array, axis=i)
    # Build the surviving axes list.
    new_axes: list[AxisMeta] = []
    for axis, (indices, collapse) in zip(axes, per_axis):
        if collapse:
            continue
        if indices is None:
            new_axes.append(axis)
        else:
            new_axes.append(
                replace(axis, levels=tuple(axis.levels[j] for j in indices))
            )
    return out_array, tuple(new_axes)

def _group_into_steps(plans: tuple[_NodePlan, ...]) -> tuple[_Step, ...]:
    """Partition a topologically ordered plan list into runtime steps.

    A bundle's step sits at the position of its **last** member, because that is
    the first point in the order at which every member's parents have values.
    Members keep their own identity throughout; only the draw is shared.

    Two conditions are checked here rather than left to fail obscurely at trace
    time:

    - every member's constructor declares a ``site_fn``. Desugar already
      refuses this at config time, but a hand-built graph reaches compile
      without passing through desugar.
    - no member is a transitive ancestor of another member. That is not a
      technicality: computing the second member's parameters would need the
      first member's *value*, which does not exist until the shared site is
      drawn. Requiring it is a cycle through the bundle.
    """
    members: dict[str, list[_NodePlan]] = {}
    for plan in plans:
        bundle = plan.meta.bundle_id
        if bundle is not None:
            members.setdefault(bundle, []).append(plan)

    # Transitive ancestors, accumulated in topological order so each node's
    # parents are already resolved when it is reached.
    ancestors: dict[str, frozenset[str]] = {}
    for plan in plans:
        acc: frozenset[str] = frozenset()
        for pid in plan.parent_ids:
            acc |= ancestors.get(pid, frozenset()) | {pid}
        ancestors[plan.meta.node_id] = acc

    for bundle, group in members.items():
        ids = frozenset(p.meta.node_id for p in group)
        for plan in group:
            if not plan.entry.bundlable:
                raise ValueError(
                    f"node {plan.meta.node_id!r} is in bundle {bundle!r} but its "
                    "constructor declares no site_fn, so it has no parameters "
                    "to contribute to a shared site"
                )
            if inner := sorted(ids & ancestors[plan.meta.node_id]):
                raise ValueError(
                    f"node {plan.meta.node_id!r} depends on {inner}, which "
                    f"share its bundle {bundle!r}; a member's parameters would "
                    "need another member's value, which does not exist until "
                    "the shared site is drawn"
                )

    last: dict[str, str] = {b: g[-1].meta.node_id for b, g in members.items()}
    steps: list[_Step] = []
    for plan in plans:
        bundle = plan.meta.bundle_id
        if bundle is None:
            steps.append(_Step(plans=(plan,)))
        elif last[bundle] == plan.meta.node_id:
            steps.append(_Step(plans=tuple(members[bundle]), bundle=bundle))
    return tuple(steps)

def _is_flat_bundle(parent: StructuredArray) -> bool:
    """True if ``parent`` is a flat prior bundle (single ``_bundle`` axis)."""
    return (
        parent.array.ndim == 1
        and len(parent.axes) == 1
        and parent.axes[0].name == BUNDLE_AXIS_NAME
    )

def _role_keyed(
    plan: _NodePlan, sampled: Mapping[str, StructuredArray]
) -> dict[str, tuple[StructuredArray, ...]]:
    """Project ``sampled`` (keyed by parent id) into role-keyed parent values.

    Includes M4 unbundling: a shared bundle parent is projected to this
    consumer's ``(node_id, role)`` block before the CPD sees it. Shared by the
    solo and bundled paths, because a member's parents are read exactly as a
    lone node's are -- what bundling changes is the draw, not the reading.
    """
    consumer_id = plan.meta.node_id
    role_keyed: dict[str, tuple[StructuredArray, ...]] = {}
    for role, pids in plan.resolved_bindings.items():
        decl = plan.entry.parameter_schema.get(role)
        if decl is not None and decl.receives_bundle_atoms:
            # Plural projection: one bundle node expands to its several atoms.
            vals: list[StructuredArray] = []
            for pid in pids:
                vals.extend(
                    _project_parent_atoms(
                        sampled[pid], consumer_id=consumer_id, role=role
                    )
                )
            role_keyed[role] = tuple(vals)
        else:
            role_keyed[role] = tuple(
                _project_parent_value(
                    sampled[pid], consumer_id=consumer_id, role=role
                )
                for pid in pids
            )
    return role_keyed

def deterministic_fn(name: str, value: Any, step: Any = None) -> Any:
    del step
    if interventions.has(name):
        out = numpyro.deterministic(name, interventions.value_for(name))
    else:
        out = numpyro.deterministic(name, value)
    # Same coercion as in `_build_sample_fn`: normalize to a JAX
    # array so callers get a uniform return type whether the value
    # came from the CPD's own computation or from an intervention
    # override (which may be a raw Python scalar).
    return jnp.asarray(out)

def model_observations(graph: Any) -> pd.DataFrame:
    """One row per observation node: ``node_id``, ``indicator``, ``source``, ``unit``.

    Found by what a node *carries* rather than by its role name: an observation
    grid is exactly the node whose hyperparameters name an indicator and a
    source, which is the same pair the tracker indexes on. Reading the shape
    rather than the spelling means a config free to name its roles differently
    still lands here.
    """
    rows = []
    for meta in graph.nodes():
        hyper = getattr(meta.cpd_spec, "hyperparameters", None) or {}
        if "indicator" not in hyper or "source" not in hyper:
            continue
        rows.append(
            {
                "node_id": meta.node_id,
                "indicator": str(hyper["indicator"]),
                "source": str(hyper["source"]),
                "unit": str(hyper.get("unit", "")),
            }
        )
    if not rows:
        raise ValueError(
            "no node in this graph names both an indicator and a source, so "
            "there are no observations to describe; the tracker highlights "
            "report what the model reads from the data"
        )
    return pd.DataFrame(rows).sort_values(["indicator", "source"], ignore_index=True)

def _long_frame(array: StructuredArray) -> pd.DataFrame:
    """Every cell of ``array`` as a row: one column per axis, plus ``value``.

    The cross product of the axes' levels in axis order is exactly the array's
    C-order ravel, which is what makes this a reshape rather than a lookup.
    """
    axes = array.axes
    values = np.asarray(array.array).reshape(-1)
    if not axes:
        return pd.DataFrame({"value": values})
    index = pd.MultiIndex.from_product(
        [list(axis.levels) for axis in axes],
        names=[axis.name for axis in axes],
    )
    return pd.DataFrame({"value": values}, index=index).reset_index()

def _tagged(level: Any) -> str:
    """One level as a type tag plus normalized text.

    The tag keeps ``2019`` and ``"2019"`` apart -- their coord dtypes differ, so
    they must not share a dim -- while the normalization puts numpy scalars on
    the same bytes as their Python equivalents, since ``AxisMeta.levels`` can
    hold either and the same logical level must not digest two ways.
    """
    if isinstance(level, str):
        return "s:" + str(level)
    # bool before int: bool is an int subclass.
    if isinstance(level, (bool, np.bool_)):
        return "b:" + ("1" if level else "0")
    if isinstance(level, (int, np.integer)):
        return "i:" + str(int(level))
    if isinstance(level, (float, np.floating)):
        return "f:" + repr(float(level))
    return "o:" + str(level)

def parse_level(tag: str, text: str) -> Any:
    """Invert ``level_text``."""
    if tag not in _UNTAG:
        raise ValueError(
            f"level type {tag!r} is not one this reader knows "
            f"({', '.join(sorted(_UNTAG))})"
        )
    return _UNTAG[tag](text)

def assemble_posterior(
    prepared: Sequence[tuple[str, np.ndarray, Sequence[str], Mapping[str, list]]],
) -> object:
    """Build the container from arrays that already carry their sample dims.

    Split out from ``to_inference_data`` because the suffix rule has to hold for
    everything that ever builds a container -- a fit and a file read back -- and
    two copies of it could drift into naming the same node's dims differently.
    What is left in ``to_inference_data`` is the part that is genuinely about a
    fit: reading ``StructuredArray`` axes and prepending ``(chain, draw)``.

    Each entry is ``(node_id, array, dim_names, coords)`` with ``dim_names``
    the **bare** axis names of the trailing (domain) dims, in order.
    """
    level_sets: dict[str, set[tuple]] = {}
    for _, _, _, node_coords in prepared:
        for name, levels in node_coords.items():
            level_sets.setdefault(name, set()).add(tuple(levels))

    ambiguous = {name for name, seen in level_sets.items() if len(seen) > 1}

    posterior: dict[str, np.ndarray] = {}
    dims: dict[str, list[str]] = {}
    coords: dict[str, list] = {}
    for node_id, array, dim_names, node_coords in prepared:
        posterior[node_id] = array
        resolved = {
            name: _resolved_dim(name, node_coords[name], ambiguous)
            for name in node_coords
        }
        dims[node_id] = [resolved[name] for name in dim_names]
        for name, levels in node_coords.items():
            coords[resolved[name]] = list(levels)

    return arviz.from_dict({"posterior": posterior}, coords=coords, dims=dims)

def _bare_dim(dim: str, levels: Sequence[Any]) -> str:
    """``dim`` without its level-set suffix, if that is what the tail is."""
    head, sep, tail = dim.rpartition(SUFFIX_SEP)
    if sep and tail == level_set_suffix(levels):
        return head
    return dim

def _native(level: Any) -> Any:
    """A numpy coordinate scalar as the Python object it stands for.

    xarray hands back ``np.str_``/``np.int64``; the levels that went in were
    Python objects, and equality of a round trip is judged on those.
    """
    if isinstance(level, np.generic):
        return level.item()
    return level

def _resolved_dim(name: str, levels: Sequence[Any], ambiguous: set[str]) -> str:
    """The output dim name for one axis: bare, or suffixed by its level set."""
    if name not in ambiguous:
        return name
    return f"{name}{SUFFIX_SEP}{level_set_suffix(levels)}"

def _finite_number(value: Any) -> float | None:
    number = float(value)
    return number if np.isfinite(number) else None

def _json_scalar(value: Any) -> Any:
    """Allow NumPy scalar axis levels without serializing arbitrary objects."""
    if isinstance(value, np.generic):
        return value.item()
    raise TypeError(f"not JSON serializable: {type(value).__name__}")

def _resolve_shares_node(
    result: InferenceResult, shares_node: str | None
) -> str | None:
    """The segmentation node for curated sheets, or ``None`` if there is none."""
    if shares_node is not None:
        return shares_node
    from_special = result.node_for_special(SEGMENTATION_SPECIAL)
    if from_special is not None:
        return from_special
    if _DEMO_SHARES_NODE in result.posterior:
        return _DEMO_SHARES_NODE
    return None

def _resolve_population_node(
    result: InferenceResult, population_node: str | None
) -> str | None:
    """The population node for people-weighted columns, if any."""
    if population_node is not None:
        return population_node
    from_special = result.node_for_special(POPULATION_SPECIAL)
    if from_special is not None:
        return from_special
    if _DEMO_POPULATION_NODE in result.posterior:
        return _DEMO_POPULATION_NODE
    return None

def observed_country_years_by_indicator(
    loaded: Any,
) -> dict[str, set[tuple[Any, Any]]]:
    """``indicator -> {(country, year), ...}`` cells with at least one loaded row."""
    cells: dict[str, set[tuple[Any, Any]]] = {}
    for rec in loaded.records:
        country = rec.levels.get("country")
        year = rec.levels.get("year")
        if country is None or year is None:
            continue
        cells.setdefault(rec.indicator, set()).add((country, year))
    return cells

def _country_column(frame: pd.DataFrame) -> str | None:
    """Country axis column in a tidy or wide parameter table."""
    if "country" in frame.columns:
        return "country"
    for col in frame.columns:
        if str(col).startswith("country"):
            return str(col)
    return None

def __setattr__(self, name: str, value: Any) -> None:
    # D7: the result is immutable; predict/refit return new objects rather
    # than mutating. Block attribute reassignment after construction.
    raise AttributeError(
        f"{type(self).__name__} is immutable; cannot set {name!r}"
    )

def __delattr__(self, name: str) -> None:
    raise AttributeError(
        f"{type(self).__name__} is immutable; cannot delete {name!r}"
    )

def __eq__(self, other: Any) -> bool:
    """Equal iff the same nodes, in order, with the same arrays and metadata.

    Exists so a round trip through the serializer is a claim about
    something: "``load(save(r)) == r``" is only as strong as what equality
    compares. Node *order* counts because it is what the writer preserves
    and what a file diff shows; ``nan`` compares equal to ``nan`` because
    the question is whether the bytes survived, not whether the numbers are
    meaningful. Metadata counts because the writer now promises it back --
    a result that reloaded with the right numbers under the wrong
    ``family`` would aggregate wrongly and pass.
    """
    if not isinstance(other, InferenceResult):
        return NotImplemented
    if self._scenario != other._scenario:
        return False
    if not _same_array(self._losses, other._losses):
        return False
    if list(self._sampled) != list(other._sampled):
        return False
    if self._specials != other._specials:
        return False
    return all(
        _same_structured(array, other._sampled[node_id])
        for node_id, array in self._sampled.items()
    )

@property
def node_ids(self) -> tuple[str, ...]:
    """The nodes this result holds, in the order the fit produced them."""
    return tuple(self._sampled)

def sampled(self) -> Mapping[str, StructuredArray]:
    """The whole map, as a read-only view."""
    return MappingProxyType(self._sampled)

@property
def posterior(self):
    """The posterior group as an xarray ``Dataset`` (supports ``.sel``)."""
    return self.as_inference_data()["posterior"].to_dataset()

@property
def scenario(self) -> Any:
    """Scenario metadata, or ``None`` for a base (non-scenario) fit."""
    return self._scenario

def segment_shares(self, country: Any, year: Any):
    """Segment shares for one ``(country, year)`` -- the K-simplex vector.

    Named wrapper over ``samples("segment_shares", country=..., year=...)``;
    equals ``self.posterior.segment_shares.sel(country=..., year=...)``.
    """
    return self.samples("segment_shares", country=country, year=year)

def _highlight_segmentation_latest(
    self,
    out: Path,
    *,
    graph: Any = None,
    now: datetime | None = None,
) -> Path:
    """Segmentation shares for the most recent non-future year on the axis."""
    del graph
    frame, _ = self._segmentation_sheet()
    if "year" not in frame.columns:
        raise ValueError(
            "the segmentation numbers have no `year` column, so there is no "
            "single year to report; use the `segmentation_series` highlight"
        )
    year = _highlights.latest_year(frame["year"].unique(), now=now)
    frame = frame[frame["year"] == year].drop(columns=["year"])
    return _highlights.write_sheet(
        frame, out / f"segmentation_{year}.xlsx"
    )

def _model_and_tracker(
    self, graph: Any, tracker: Any
) -> tuple[Any, Any]:
    """``(graph, tracker frame)``, refusing early when the graph is missing.

    The two tracker sheets describe the *model*, not the fit, and a result
    deliberately does not keep the graph it came from. So the caller has to
    hand it over, and the error has to say that rather than raising an
    ``AttributeError`` somewhere in the walk.
    """
    if graph is None:
        raise ValueError(
            "the tracker highlights describe which indicators the model "
            "reads, which is a fact about the graph; pass `graph=` to "
            "`highlights()`"
        )
    return graph, _highlights.read_tracker(tracker)

def _highlight_model_indicators(
    self,
    out: Path,
    *,
    graph: Any = None,
    tracker: str | Path | None = None,
) -> Path:
    """Every (indicator, source) the model reads, as the tracker describes it."""
    graph, frame = self._model_and_tracker(graph, tracker)
    return _highlights.write_model_indicators_workbook(
        _highlights.indicator_table(graph, frame), out / "model_indicators.xlsx"
    )

def _highlight_tracker_coverage(
    self,
    out: Path,
    *,
    graph: Any = None,
    tracker: str | Path | None = None,
) -> Path:
    """How many of each tracker cluster's indicators the model uses."""
    graph, frame = self._model_and_tracker(graph, tracker)
    return _highlights.write_sheet(
        _highlights.cluster_coverage(graph, frame), out / "tracker_coverage.xlsx"
    )

def _prepare(node_id: str, array: Any) -> StructuredArray:
    """One map entry, checked and stamped with its own identity.

    A fit's arrays arrive already stamped (``compile._dispatch_node`` does it),
    but a hand-built or reloaded map need not be, and an unstamped array would
    make ``load(save(r)) == r`` false for a reason about bookkeeping rather than
    content. Stamping here rather than requiring it of callers keeps
    ``structured(x).node_id == x`` unconditionally true. A *disagreeing* stamp
    is refused: that means the map was assembled wrongly, and guessing which
    name is the real one would hide it.
    """
    if not isinstance(array, StructuredArray):
        raise TypeError(
            f"node {node_id!r}: an InferenceResult holds StructuredArrays, not "
            f"{type(array).__name__}"
        )
    if array.node_id is None:
        return replace(array, node_id=node_id)
    if array.node_id != node_id:
        raise ValueError(
            f"node {node_id!r} carries node_id {array.node_id!r}; the map's key "
            "and the array's own identity have to agree"
        )
    return array

def _prepare_specials(
    specials: Mapping[str, Any] | None,
    sampled: Mapping[str, StructuredArray],
) -> dict[str, tuple[str, ...]]:
    """The specials map, normalized and checked against the nodes it describes.

    Empty entries are dropped rather than stored, so two results that differ
    only in whether a node was passed an empty tuple compare equal -- the
    absence of a special and an empty list of them are the same fact.

    Two refusals, both about a map that cannot be true of this result: a node
    id the result does not hold (the map was built against a different graph,
    or a node was filtered out of the fit after the specials were collected),
    and one special on two nodes (see ``node_for_special``).
    """
    if not specials:
        return {}
    prepared: dict[str, tuple[str, ...]] = {}
    owner: dict[str, str] = {}
    for node_id, names in specials.items():
        if node_id not in sampled:
            raise KeyError(
                f"specials name node {node_id!r}, which this result does not "
                f"hold; it holds {list(sampled)!r}"
            )
        names = tuple(names)
        for name in names:
            if name in owner:
                raise ValueError(
                    f"special {name!r} is claimed by both {owner[name]!r} and "
                    f"{node_id!r}; a special marks one node"
                )
            owner[name] = node_id
        if names:
            prepared[node_id] = names
    return prepared

def _same_structured(a: StructuredArray, b: StructuredArray) -> bool:
    """Two node arrays, equal in values and in every piece of metadata."""
    if (a.node_id, a.axes, a.indicator) != (b.node_id, b.axes, b.indicator):
        return False
    if (a.population is None) != (b.population is None):
        return False
    if a.population is not None and not _same_structured(a.population, b.population):
        return False
    return _same_array(np.asarray(a.array), np.asarray(b.array))

def _same_array(a: Any, b: Any) -> bool:
    """Two optional arrays, equal bitwise, with ``nan`` equal to itself."""
    if a is None or b is None:
        return a is None and b is None
    a, b = np.asarray(a), np.asarray(b)
    if a.shape != b.shape or a.dtype != b.dtype:
        return False
    if a.dtype.kind == "f":
        return bool(np.array_equal(a, b, equal_nan=True))
    return bool(np.array_equal(a, b))

def _refuse_unwritable(node_id: str, sa: StructuredArray) -> None:
    """Refuse a node whose metadata has no faithful written form yet.

    Both of these are unset everywhere in the pipeline today. The alternative
    to refusing is writing a file that reads back with the field missing, which
    would make the round trip quietly untrue for the first caller to set one.
    """
    if sa.population is not None:
        raise NotImplementedError(
            f"node {node_id!r} carries a population pointer, which has no "
            "written form yet: it should be saved as a reference to the "
            "population node, not as a nested table"
        )
    for axis in sa.axes:
        if axis.basis is not None:
            raise NotImplementedError(
                f"node {node_id!r}, axis {axis.name!r} carries a basis "
                f"({axis.basis!r}), which has no written form yet"
            )

def _write_losses(path: Path, losses: np.ndarray) -> None:
    with path.open("w", newline="", encoding="utf-8") as handle:
        writer = csv.writer(handle)
        writer.writerow(["step", "loss"])
        for step, value in enumerate(losses):
            writer.writerow([step, _number(value)])

def _read_losses(path: Path, dtype: np.dtype) -> np.ndarray:
    with path.open(newline="", encoding="utf-8") as handle:
        rows = list(csv.reader(handle))[1:]
    return np.asarray([dtype.type(row[1]) for row in rows], dtype=dtype)

def _declared_upstream_standardizer_id(config: GraphConfig, root_id: str) -> str | None:
    """The standardize child of ``root_id`` if declared, else ``None``."""
    standardize_ids = {
        node.id
        for node in config.nodes
        if node.cpd is not None and node.cpd.family == "standardize"
    }
    for edge in config.edges:
        if edge.parent == root_id and edge.child in standardize_ids:
            return edge.child
    return None

def _attach_upstream_driver_pairs(
    graph: BayesGraph,
    config: GraphConfig,
    anchor,
    cpd_spec_cls: Any,
    *,
    data_resolver: DataResolver | None,
) -> None:
    """Synthesize ``_z`` standardizers + wiring for upstream driver roots.

    For each ``indicator_role: upstream`` root whose standardizer chain is not
    already declared, add ``{root}_z`` (``family: standardize``) and wire
    ``root -> _z -> anchor``. Absence-triggered per driver; explicit ``_z`` nodes
    or edges suppress synthesis for that driver only.
    """
    from digital_readiness.core.graph import NodeMeta

    declared_edges = {(e.parent, e.child) for e in config.edges}

    for root in config.nodes:
        if (root.extra or {}).get("indicator_role") != UPSTREAM_INDICATOR_ROLE:
            continue
        z_id = f"{root.id}{_UPSTREAM_STANDARDIZER_SUFFIX}"
        if _declared_upstream_standardizer_id(config, root.id) is not None:
            continue  # standardizer declared -> config wins
        if z_id in graph:
            continue

        transform = str((root.extra or {}).get("transform", "identity"))
        data_ind = data_indicator_for_standardize(root)
        std_args = {"indicator": data_ind, "transform": transform}
        hp_raw = {
            "center": {DATA_REF_KEY: "standardize.center", "args": std_args},
            "scale": {DATA_REF_KEY: "standardize.scale", "args": std_args},
            "transform": transform,
        }
        hp = {
            key: _plain_hyperparameter(
                value,
                data_resolver,
                f"upstream driver {root.id!r} standardize {key!r}",
            )
            for key, value in hp_raw.items()
        }

        graph.add_node(
            NodeMeta(
                node_id=z_id,
                kind="zscore",
                # A standardization node stands for its parent's quantity on a
                # rescaled scale, so it names the parent's sheet code, not one of
                # its own -- the same inheritance ``desugar``'s
                # ``resolve_inherited_indicators`` applies on the ``normalize:``
                # path. This
                # synthesis does not run through desugar, so it says so here.
                indicator=data_ind,
                cpd_spec=cpd_spec_cls(
                    family="standardize",
                    constructor=None,
                    hyperparameters=hp,
                ),
            )
        )
        if (root.id, z_id) not in declared_edges:
            graph.add_edge(root.id, z_id)
        if (z_id, anchor.id) not in declared_edges:
            graph.add_edge(z_id, anchor.id)

def _find_continuation_ratio_anchor(config: GraphConfig):
    """The single Type-II ``continuation_ratio`` node, or ``None`` if absent.

    Detection is by CPD family, never by node id -- the anchor's presence (not
    its name) is what triggers downstream manifestation synthesis.
    """
    for node in config.nodes:
        if node.cpd is not None and node.cpd.family == _CONTINUATION_RATIO_FAMILY:
            return node
    return None

def _is_downstream_profile(node, *, allow_indicator_role: bool = True) -> bool:
    """Whether ``node`` is a profile prior eligible for manifestation synthesis.

    ``manifestation_role: profile`` is the intended tag. ``indicator_role:
    downstream`` is a <=v3 alias for it, honored only when
    ``allow_indicator_role`` -- on v4 a node's part in the manifestation chain is
    stated by the chain itself, not inferred from an indicator-facing tag.
    """
    extra = node.extra or {}
    if extra.get("manifestation_role") == _MANIFESTATION_PROFILE_ROLE:
        return True
    return allow_indicator_role and (
        extra.get("indicator_role") == _DOWNSTREAM_INDICATOR_ROLE
    )

def _mean_id_for_profile(profile_node) -> str:
    """Conventional mixture-mean id for a downstream profile prior."""
    extra = profile_node.extra or {}
    if "mean_id" in extra:
        return str(extra["mean_id"])
    profile_id = profile_node.id
    if profile_id.startswith(_DOWNSTREAM_PROFILE_PREFIX):
        return f"{profile_id[len(_DOWNSTREAM_PROFILE_PREFIX):]}{_DOWNSTREAM_MEAN_SUFFIX}"
    return f"{profile_id}{_DOWNSTREAM_MEAN_SUFFIX}"

def _declared_manifestation_child(config: GraphConfig, profile_id: str) -> str | None:
    """The declared manifestation child of ``profile_id``, if any."""
    manifestation_ids = {
        node.id
        for node in config.nodes
        if node.cpd is not None and node.cpd.family == _MANIFESTATION_FAMILY
    }
    for edge in config.edges:
        if edge.parent == profile_id and edge.child in manifestation_ids:
            return edge.child
    return None

def _attach_downstream_manifestation_pairs(
    graph: BayesGraph,
    config: GraphConfig,
    shares_anchor,
    cpd_spec_cls: Any,
) -> None:
    """Synthesize mixture-mean nodes + wiring for downstream profile priors.

    For each profile prior whose manifestation chain is not already declared,
    add ``{base}_mean`` (``family: manifestation``) and wire
    ``segment_shares -> mean <- profile``. Absence-triggered per profile;
    explicit mean nodes or edges suppress synthesis for that profile only.
    """
    from digital_readiness.core.graph import NodeMeta

    declared_edges = {(e.parent, e.child) for e in config.edges}

    for profile in config.nodes:
        if not _is_downstream_profile(
            profile, allow_indicator_role=config.version < 4
        ):
            continue
        if _declared_manifestation_child(config, profile.id) is not None:
            continue  # manifestation declared -> config wins
        mean_id = _mean_id_for_profile(profile)
        if mean_id not in graph:
            graph.add_node(
                NodeMeta(
                    node_id=mean_id,
                    kind="mixture_mean",
                    cpd_spec=cpd_spec_cls(
                        family=_MANIFESTATION_FAMILY,
                        constructor=None,
                        hyperparameters={},
                    ),
                )
            )
        if (shares_anchor.id, mean_id) not in declared_edges:
            graph.add_edge(shares_anchor.id, mean_id)
        if (profile.id, mean_id) not in declared_edges:
            graph.add_edge(profile.id, mean_id)

def _synthesized_theta_weight_loc(
    config: GraphConfig, axes: tuple[AxisMeta, ...]
) -> float | list:
    """Adapter: ``desugar.synthesized_weight_loc`` over resolved ``AxisMeta``."""
    return synthesized_weight_loc(config, [(ax.name, ax.levels) for ax in axes])

def _family_obs_template(config: GraphConfig, family: str) -> dict[str, Any]:
    """Built-in per-family obs template, with optional ``observation_defaults`` overlay."""
    template = dict(_FAMILY_OBS_TEMPLATE.get(family, {}))
    if config.observation_defaults is not None:
        template.update(config.observation_defaults.family_obs_override(family))
    return template

def _obs_node_meta(bundle, cells: tuple, template: dict[str, Any], cpd_spec_cls: Any):
    """A Type-III obs ``NodeMeta`` for one bundle, gated to ``cells``."""
    from digital_readiness.core.graph import NodeMeta

    return NodeMeta(
        node_id=bundle.site_id,
        kind="observation",
        cpd_spec=cpd_spec_cls(
            family=bundle.family,
            constructor="observation",
            hyperparameters={"cells": cells, **template},
        ),
    )

def make_observation_resolver(observations: LoadedObservations) -> DataResolver:
    """Build a :class:`DataResolver` that reads panel-derived values from data.

    The returned callable dispatches on ``ref.source`` (see the module table).
    It closes over ``observations`` so the build step injects it once
    (``build_graph(config, observations, data_resolver=make_observation_resolver(observations))``).
    """
    # indicator -> [(cell, value)], values pulled to python floats once. The
    # loader keeps cells and values parallel within a bundle; an indicator may
    # span more than one family bundle, so we flatten across all of them.
    pairs_by_indicator: dict[str, list[tuple[dict[str, Any], float]]] = {}
    for bundle in observations.cell_bundles:
        for cell, value in zip(bundle.cells, bundle.values):
            pairs_by_indicator.setdefault(str(cell["indicator"]), []).append(
                (cell, float(value))
            )

    def resolve(ref: DataRef) -> Any:
        source = ref.source
        if source in ("standardize.center", "standardize.scale"):
            return _standardize(pairs_by_indicator, source, ref.args)
        if source == "country.levels":
            return _country_levels(observations)
        if source == "pop.weights_FM":
            return _cell_pop_weights(pairs_by_indicator, ref.args)
        raise ValueError(
            f"unknown data source {source!r}; the resolver vocabulary is "
            "{standardize.center, standardize.scale, country.levels, pop.weights_FM}"
        )

    return resolve

def resolve(ref: DataRef) -> Any:
    source = ref.source
    if source in ("standardize.center", "standardize.scale"):
        return _standardize(pairs_by_indicator, source, ref.args)
    if source == "country.levels":
        return _country_levels(observations)
    if source == "pop.weights_FM":
        return _cell_pop_weights(pairs_by_indicator, ref.args)
    raise ValueError(
        f"unknown data source {source!r}; the resolver vocabulary is "
        "{standardize.center, standardize.scale, country.levels, pop.weights_FM}"
    )

def _values_for(
    pairs_by_indicator: dict[str, list[tuple[dict[str, Any], float]]],
    indicator: str,
    what: str,
) -> list[tuple[dict[str, Any], float]]:
    pairs = pairs_by_indicator.get(indicator)
    if not pairs:
        raise ValueError(
            f"{what}: no observation cells for indicator {indicator!r}; "
            f"available indicators: {sorted(pairs_by_indicator)}"
        )
    return pairs

def _country_levels(observations: LoadedObservations) -> tuple[str, ...]:
    """Sorted unique country codes present across all loaded cells.

    Mirrors ``load_panel``'s ``tuple(sorted(d.country_iso3.unique()))`` -- the
    ``country`` axis levels are a property of the observed sample, not config.
    """
    geos = {
        str(cell["unit"][0])
        for bundle in observations.cell_bundles
        for cell in bundle.cells
    }
    return tuple(sorted(geos))

def _split_prior_blocks(value) -> tuple[PriorDef | None, dict[str, PriorDef]]:
    """Read one ``priors.<role>`` value as (shared block, per-key blocks).

    The single-node form is all shared and has no keys; the keyed form splits at
    the reserved :data:`_SHARED_PRIOR_KEY`. Callers downstream of this see one
    shape, so nothing else has to know which spelling the author used.
    """
    if value is None:
        return None, {}
    if isinstance(value, PriorDef):
        return value, {}
    per_key = {k: v for k, v in value.items() if k != _SHARED_PRIOR_KEY}
    return value.get(_SHARED_PRIOR_KEY), per_key

def _merge_prior_defs(base: PriorDef, over: PriorDef | None) -> PriorDef:
    """Lay an author-written block over a walk-supplied default block.

    Field by field, the author wins where they wrote something -- including
    inside ``cpd``, so pinning one hyperparameter does not discard the rest.
    """
    if over is None:
        return base
    merged_cpd = base.cpd
    if over.cpd is not None:
        merged_cpd = (
            over.cpd
            if merged_cpd is None
            else merged_cpd.model_copy(
                update={
                    **{
                        name: value
                        for name, value in over.cpd.model_dump(
                            exclude_unset=True
                        ).items()
                        if name not in ("hyperparameters", "priors")
                    },
                    "hyperparameters": {
                        **merged_cpd.hyperparameters,
                        **over.cpd.hyperparameters,
                    },
                    "priors": {**merged_cpd.priors, **over.cpd.priors},
                }
            )
        )
    return base.model_copy(
        update={
            "id": over.id if over.id is not None else base.id,
            "include_axes": over.include_axes or base.include_axes,
            "bundle_id": (
                over.bundle_id if over.bundle_id is not None else base.bundle_id
            ),
            "cpd": merged_cpd,
        }
    )

def data_indicator_for_standardize(node: NodeDef) -> str:
    """Spreadsheet indicator code for ``standardize.center`` / ``scale`` binding.

    The driver-axis level is the node's id (``income``); the data-sheet code may
    differ (``dispinc_pc``). Prefer an explicit ``extra.data_indicator``; else
    read ``indicator`` from a ``standardize.center`` data-ref on the root's ``loc``
    hyperparameter (the income pattern in ``demo_v0.yaml``); else the declared
    top-level ``indicator``; else ``node.id``.

    The declared field is consulted ahead of the id because that is what it is for:
    the node's primary sheet code, which a standardization of that node has to bind
    to. Before v4 there was no such field and the id was the only fallback, so a
    v4 node whose id differs from its code (``income``/``dispinc_pc``) failed the
    lookup unless it restated the code in ``extra.data_indicator``. Nothing changes
    for a config that does not declare ``indicator``, which is every config at
    v<=3. ``extra.indicator`` remains reserved for the obs gate and is still NOT
    read here, so a root can keep ``driver`` level ``income`` either way.

    Shared with ``build.py``'s tag-triggered zscore synthesis
    (``_attach_upstream_driver_pairs``) so the ``expand_parents`` pass and the
    build step derive the indicator by literally the same rule.
    """
    extra = node.extra or {}
    if "data_indicator" in extra:
        return str(extra["data_indicator"])
    hp = (node.cpd.hyperparameters if node.cpd is not None else {}) or {}
    for key in ("loc", "center"):
        value = hp.get(key)
        if not is_data_ref(value):
            continue
        if isinstance(value, dict):
            source = value.get(DATA_REF_KEY)
            args = value.get("args", {})
        else:
            source = value.source
            args = value.args
        if source == "standardize.center":
            return str(args.get("indicator", node.id))
    if node.indicator:
        return str(node.indicator)
    return node.id

def _add_edge(
    edges: list[EdgeDef], edge_pairs: set[tuple[str, str]], parent: str, child: str
) -> None:
    """Append ``[parent, child]`` unless already declared (raw duplicates are
    tolerated -- the §C ruling)."""
    if (parent, child) in edge_pairs:
        return
    edges.append(EdgeDef(parent=parent, child=child))
    edge_pairs.add((parent, child))

def _expand_parents(config: GraphConfig) -> GraphConfig:
    """Lower inline ``NodeDef.parents`` refs to top-level edges.

    A bare ref becomes the ``[parent, node]`` edge; a ref with ``normalize``
    becomes ``parent -> parent_z -> node`` plus the synthesized standardize
    node. Rulings encoded (scope doc §C):

    - duplicate raw edge -> tolerated, deduped;
    - raw DIRECT edge alongside a normalized route -> inline wins, the direct
      edge is dropped with a warning (keeping both would give the consumer two
      paths from the same parent);
    - synthesized id colliding with a declared node -> error (two specs for
      one site; unlike build's absence-triggered synthesis there is nothing to
      quietly suppress -- the author affirmatively wrote both);
    - two refs synthesizing the same id -> fine if the synthesized specs are
      identical (shared standardizer), error otherwise.
    """
    if not any(node.parents for node in config.nodes):
        return config
    nodes_by_id = {node.id: node for node in config.nodes}
    edges = list(config.edges)
    edge_pairs = {(e.parent, e.child) for e in edges}
    synthesized: dict[str, NodeDef] = {}
    out_nodes: list[NodeDef] = []

    for node in config.nodes:
        for ref in node.parents:
            if ref.normalize is None:
                _add_edge(edges, edge_pairs, ref.id, node.id)
                continue
            parent = nodes_by_id.get(ref.id)
            if parent is None:
                raise ValueError(
                    f"node {node.id!r} names inline parent {ref.id!r} with a "
                    f"normalizer, but no such node is declared"
                )
            z_node = _normalizer_node(parent, ref.normalize, config.version)
            if z_node.id in nodes_by_id:
                raise ValueError(
                    f"inline normalizer on parent {ref.id!r} of {node.id!r} would "
                    f"synthesize node {z_node.id!r}, but that node is already "
                    f"declared -- drop the normalizer (and wire the declared node "
                    f"explicitly) or the declared node"
                )
            previous = synthesized.get(z_node.id)
            if previous is not None and previous != z_node:
                raise ValueError(
                    f"two inline normalizers synthesize node {z_node.id!r} with "
                    f"differing specs -- name them apart via `normalize.id`"
                )
            synthesized[z_node.id] = z_node
            if (ref.id, node.id) in edge_pairs:
                warnings.warn(
                    f"edge [{ref.id}, {node.id}] is superseded by the inline "
                    f"normalizer route {ref.id} -> {z_node.id} -> {node.id}; "
                    f"dropping the direct edge (inline parents are authoritative)",
                    UserWarning,
                    stacklevel=2,
                )
                edges = [
                    e for e in edges if (e.parent, e.child) != (ref.id, node.id)
                ]
                edge_pairs.discard((ref.id, node.id))
            _add_edge(edges, edge_pairs, ref.id, z_node.id)
            _add_edge(edges, edge_pairs, z_node.id, node.id)
        out_nodes.append(
            node.model_copy(update={"parents": []}) if node.parents else node
        )

    return config.model_copy(
        update={"nodes": out_nodes + list(synthesized.values()), "edges": edges}
    )

def _spec_of(roles: Mapping[str, NodeRoleSpec], role: str | None) -> NodeRoleSpec:
    """The answers for ``role``, per the config's resolved role section.

    Two cases fall through to the default ``NodeRoleSpec()``: an unresolvable
    node (``role is None``), and a role the section does not name. The latter is
    reachable only from the registry -- ``GraphConfig`` rejects a hand-written
    unknown role -- and the lenient answer is the behavior-preserving one,
    because a role absent from every pre-B2 frozenset got exactly the default
    spec's answers: demanded axes only, its own indicator, not observable.
    """
    if role is None:
        return NodeRoleSpec()
    return roles.get(role, NodeRoleSpec())

def registry_entry_for(cpd_def):
    """The registry ``ConstructorEntry`` for a node's CPD, or ``None``.

    Resolves ``cpd.family`` (+ optional ``cpd.constructor``) against the CPD
    registry. An omitted constructor is admitted when the family registers
    exactly one (e.g. a segmentation anchor declaring only its family).
    """
    family_table = REGISTRY.get(cpd_def.family)
    if not family_table:
        return None
    if cpd_def.constructor is not None:
        return family_table.get(cpd_def.constructor)
    if len(family_table) == 1:
        return next(iter(family_table.values()))
    return None

def resolved_axis_name(cpd_def, entry, hyperparameter_name: str) -> str:
    """Resolve a hyperparameter-name reference to the axis name it denotes.

    ``ParamDecl.axes`` and ``SegmentationAnchor.output_axis_hyperparameter``
    name axes *indirectly*, as the name of a hyperparameter (e.g.
    ``"transition_axis"``) whose value is the axis name (e.g. ``"transition"``).
    Precedence: the value set on the node's ``cpd.hyperparameters``, else the
    registered default in the family's ``hyperparameter_schema``. An
    unresolvable reference is a loud error.
    """
    hp = (cpd_def.hyperparameters if cpd_def is not None else None) or {}
    if hyperparameter_name in hp:
        return str(hp[hyperparameter_name])
    decl = entry.hyperparameter_schema.get(hyperparameter_name)
    if decl is not None and decl.default is not None:
        return str(decl.default)
    raise ValueError(
        f"cannot resolve axis name: hyperparameter {hyperparameter_name!r} is "
        "neither set on the anchor node nor carries a registered default"
    )

def resolve_axis_refs(cpd_def, entry, refs) -> tuple[str, ...]:
    """Resolve a tuple of hyperparameter-name references to axis names."""
    return tuple(resolved_axis_name(cpd_def, entry, ref) for ref in refs)

def resolve_fan_out_keys(cpd_def, entry, fan_out) -> tuple[str, ...]:
    """Resolve a :class:`core.cpd.FanOut` to this node's ordered key list.

    Family-agnostic: the keys are whatever the declared source resolves to on
    *this* node, which is what makes the child count a per-node fact rather than
    a static property of the schema.

    - ``over_axes`` resolves each reference to a list of axis names (a bare
      string reads as a one-element list) and concatenates them. Duplicates are
      dropped, first occurrence winning, since a key is an identity.
    - ``over_count`` resolves one reference to an integer n, giving ``"1".."n"``.

    An empty result is not an error: it means this node does not fan out (see
    :class:`core.cpd.FanOut`), and the caller emits one ordinary prior.

    A key that collides with a :class:`PriorDef` field name (or with the
    shared-default key) is refused: those names are how the keyed form of
    ``priors.<role>`` is told apart from the single-node form, so such a key
    would be unaddressable in config.
    """
    hp = (cpd_def.hyperparameters if cpd_def is not None else None) or {}

    if fan_out.over_count is not None:
        ref = fan_out.over_count
        if ref in hp:
            raw = hp[ref]
        else:
            decl = entry.hyperparameter_schema.get(ref)
            raw = decl.default if decl is not None else None
        if raw is None:
            return ()
        try:
            count = int(raw)
        except (TypeError, ValueError):
            raise ValueError(
                f"fan-out `over_count` names hyperparameter {ref!r}, whose value "
                f"{raw!r} is not an integer count"
            ) from None
        if count < 0:
            raise ValueError(
                f"fan-out `over_count` names hyperparameter {ref!r}, whose value "
                f"{count} is negative; a child count cannot be"
            )
        return tuple(str(i) for i in range(1, count + 1))

    keys: list[str] = []
    for ref in fan_out.over_axes or ():
        if ref in hp:
            raw = hp[ref]
        else:
            decl = entry.hyperparameter_schema.get(ref)
            raw = decl.default if decl is not None else None
        if raw is None:
            continue
        names = [raw] if isinstance(raw, str) else list(raw)
        for name in names:
            if str(name) not in keys:
                keys.append(str(name))
    reserved = set(PriorDef.model_fields) | {_SHARED_PRIOR_KEY}
    clash = [key for key in keys if key in reserved]
    if clash:
        raise ValueError(
            f"fan-out over {list(fan_out.over_axes)} resolves to key(s) "
            f"{clash}, which collide with the reserved names {sorted(reserved)} "
            f"used to address a fanned-out role in config "
            f"(`priors.<role>.<key>`); rename the axis"
        )
    return tuple(keys)

def _append_level(level: str) -> None:
    if level not in seen:
        levels.append(level)
        seen.add(level)

def infer_disaggregation_axes(
    config: GraphConfig, anchor, role_tag: str = _DEFAULT_ROLE_TAG
) -> tuple[str, ...]:
    """Disaggregation axes B for the synthesized segmentation-parameter priors.

    The walk *creates* the theta priors, so -- unlike the CPD, which reads B off
    its parents -- it must derive B here. Rule: the segmentation *cell grid* is
    the axis set every driver shares; an axis only *some* drivers carry is a
    disaggregation axis. So ``B = union(driver axes) - intersection(driver
    axes)``, in first-seen order. Driver axes are read off each driver root's
    declared ``axes`` hyperparameter (the roots ``infer_driver_levels``
    reaches). An authored ``priors.<role>`` ``axes`` hyperparameter overrides
    this inference upstream.

    # TODO(T2/H16): this union-minus-intersection rule is PROVISIONAL. The general
    # shared-Type-I-prior structure -- hence how B is derived once more CPDs each
    # carry their own priors -- is unresolved and coupled to the segmentation-seam
    # lift (config_tier2_target.md, Rider 1 BOOKMARK). Revisit when T2 lands; the
    # authored ``axes`` declaration is the escape hatch until then.
    """
    nodes_by_id = {node.id: node for node in config.nodes}
    driver_axis_lists: list[tuple[str, ...]] = []
    for driver_id in infer_driver_levels(config, anchor, role_tag):
        node = nodes_by_id.get(driver_id)
        hp = (node.cpd.hyperparameters if node is not None and node.cpd else {}) or {}
        axes = hp.get("axes")
        if axes:
            driver_axis_lists.append(tuple(axes))

    if not driver_axis_lists:
        return ()
    shared = set(driver_axis_lists[0]).intersection(*driver_axis_lists[1:])
    disagg: list[str] = []
    seen: set[str] = set()
    for axes in driver_axis_lists:
        for name in axes:
            if name not in shared and name not in seen:
                disagg.append(name)
                seen.add(name)
    return tuple(disagg)

def any_driver_signed(
    config: GraphConfig, anchor, role_tag: str = _DEFAULT_ROLE_TAG
) -> bool:
    """Whether any driver root feeding ``anchor`` carries a ``sign`` tag.

    Used to reject the normal-only ``sign``/``sign_loc`` loc steering under a
    non-normal family override (§5b): the two must not silently mix.
    """
    nodes_by_id = {node.id: node for node in config.nodes}
    for driver_id in infer_driver_levels(config, anchor, role_tag):
        node = nodes_by_id.get(driver_id)
        if node is not None and (node.extra or {}).get(_SIGN_TAG) is not None:
            return True
    return False

def signed_weight_loc_from_extra(extra: dict[str, Any] | None) -> float | None:
    """Signed weights-prior location for one driver, or ``None`` if unsigned."""
    extra = extra or {}
    sign = extra.get(_SIGN_TAG)
    if sign is None:
        return None
    if sign not in _VALID_SIGNS:
        raise ValueError(
            f"invalid {_SIGN_TAG!r} {sign!r}; expected one of {sorted(_VALID_SIGNS)}"
        )
    magnitude = float(extra.get(_SIGN_LOC_TAG, _DEFAULT_SIGN_LOC))
    return magnitude if sign == "positive" else -magnitude

def synthesized_weight_loc(
    config: GraphConfig, named_axes: list[tuple[str, tuple[str, ...]]]
) -> float | list:
    """Build the weights prior's ``loc`` from per-driver ``sign`` tags.

    ``named_axes`` is the prior's axis grid as ``(name, levels)`` pairs --
    caller-resolved, so the same builder serves build.py (which holds
    ``AxisMeta`` objects) and the desugar walk (which derives levels from the
    config). Returns scalar ``0.0`` when no driver carries ``sign`` (the
    symmetric demo default). Otherwise a dense array over the full grid whose
    value is ``driver_locs[d]`` for driver index ``d`` and constant across
    every other axis (the disaggregation axes B and ``transition``). Generic in
    the number of disaggregation axes: ``|B| = 1`` reproduces the old
    ``(gender, transition, driver)`` array bit-for-bit; ``|B| != 1`` falls out
    of the same builder.
    """
    driver_pos = next(
        (i for i, (name, _) in enumerate(named_axes) if name == "driver"), None
    )
    if driver_pos is None:
        return 0.0
    _, driver_levels = named_axes[driver_pos]

    nodes_by_id = {node.id: node for node in config.nodes}
    driver_locs: list[float] = []
    any_signed = False
    for driver_id in driver_levels:
        node = nodes_by_id.get(driver_id)
        signed = signed_weight_loc_from_extra(node.extra if node is not None else None)
        if signed is None:
            driver_locs.append(0.0)
        else:
            any_signed = True
            driver_locs.append(signed)

    if not any_signed:
        return 0.0

    shape = tuple(len(levels) for _, levels in named_axes)

    def _dense(dims: tuple[int, ...], idx: tuple[int, ...]):
        if not dims:
            return driver_locs[idx[driver_pos]]
        return [_dense(dims[1:], (*idx, i)) for i in range(dims[0])]

    return _dense(shape, ())

def _dense(dims: tuple[int, ...], idx: tuple[int, ...]):
    if not dims:
        return driver_locs[idx[driver_pos]]
    return [_dense(dims[1:], (*idx, i)) for i in range(dims[0])]

def _config_segment_count(config: GraphConfig) -> int | None:
    """The segment count K derivable from the config alone, or ``None``.

    A declared concrete ``segment`` axis wins; else the top-level
    ``segment_count`` scalar; else unknown (data-ref'd levels are opaque here).
    """
    axis = config.axes.get("segment")
    if axis is not None and not is_data_ref(axis.levels):
        return len(axis.levels)
    return config.segment_count

def _config_segment_levels(config: GraphConfig) -> tuple[str, ...] | None:
    """The segment level labels derivable from the config alone, or ``None``.

    A declared concrete ``segment`` axis's levels win (custom labels flow
    through verbatim); else the ``S1..SK`` default the anchors themselves use,
    for K from ``_config_segment_count``; else unknown.
    """
    axis = config.axes.get("segment")
    if axis is not None and not is_data_ref(axis.levels):
        return tuple(str(level) for level in axis.levels)
    k = _config_segment_count(config)
    if k is None:
        return None
    return tuple(f"S{i}" for i in range(1, k + 1))

def _derivable_axis_levels(
    config: GraphConfig, consumer: NodeDef, entry, axis_name: str, role_tag: str
) -> tuple[str, ...] | None:
    """Levels of ``axis_name`` as derivable at desugar time, or ``None``.

    Only needed for the signed-weights dense ``loc`` grid, whose array layout
    requires every axis length. A declared concrete axis in ``axes:`` wins;
    otherwise the shared :func:`structural_axis_rules` decide, which is what
    keeps this in step with ``build``'s structural-axis injection. ``None``
    means "not derivable here" -- either ``axis_name`` is not structural, or it
    needs K and the config does not pin K down.
    """
    axis = config.axes.get(axis_name)
    if axis is not None and not is_data_ref(axis.levels):
        return tuple(str(level) for level in axis.levels)
    for rule in structural_axis_rules(config, consumer, entry, role_tag):
        if rule.name != axis_name:
            continue
        if not rule.needs_segment_count:
            return rule.levels(None)
        k = _config_segment_count(config)
        return None if k is None else rule.levels(k)
    return None

def _bundle_partitioned_names(family: str, constructor: str | None) -> tuple[str, ...]:
    """Which of a bundling constructor's hyperparameters are per bundle cell.

    Read off the constructor's own ``HyperDecl.bundle_partitioned`` flags, so
    the walk never hardcodes one family's parameter names: whichever family a
    role's ``default_prior`` bundles into declares its own partitioned set, and
    the alignment rule below applies to all of them identically.
    """
    table = REGISTRY.get(family)
    entry = table.get(constructor) if table and constructor else None
    schema = (entry.hyperparameter_schema if entry is not None else None) or {}
    return tuple(
        name for name, decl in schema.items() if getattr(decl, "bundle_partitioned", False)
    )

def _expand_one_range(axis_name: str, token: str) -> list[int]:
    """One range token to its inclusive integer list, or a named error."""
    lo_str, _, hi_str = token.partition(RANGE_SEPARATOR)
    try:
        lo, hi = int(lo_str), int(hi_str)
    except ValueError:
        raise ValueError(
            f"axis {axis_name!r} has a malformed range token {token!r}: both "
            f'endpoints must be integers (e.g. "2021...2045")'
        ) from None
    if hi < lo:
        raise ValueError(
            f"axis {axis_name!r} has a descending range token {token!r}: the "
            f"first endpoint must not exceed the second"
        )
    return list(range(lo, hi + 1))

def _root_latent_axis_names(cpd_def, entry: ConstructorEntry) -> set[str]:
    """Axis names a root latent carries via its ``axes`` hyperparameter.

    A root latent (mechanical check 1) takes its shape from an ``axes``
    hyperparameter whose value is a list of axis names -- the literal set on the
    node's ``cpd.hyperparameters`` if present, else the registered
    ``HyperDecl.default``. This is the generic surface through which the demo's
    ``segment`` axis enters the universe (the two ``profile_*`` root latents
    declare ``axes: [segment]``); it is not hardcoded to any family.
    """
    hp = cpd_def.hyperparameters or {}
    if "axes" in hp:
        value = hp["axes"]
    else:
        decl = entry.hyperparameter_schema.get("axes")
        value = decl.default if decl is not None else None
    if value is None or is_data_ref(value):
        return set()
    if isinstance(value, (list, tuple)):
        return {str(v) for v in value}
    return {str(value)}

def _node_generated_axes(node: NodeDef) -> set[str]:
    """Axis names a node's CPD contributes to the universe, generically.

    Three registry-generic surfaces, no family names hardcoded (decision 5):
    each ``ParamDecl.axes`` reference resolved to an axis name; a segmentation
    anchor's output axis via ``SegmentationAnchor.output_axis_hyperparameter``;
    and a root latent's ``axes`` hyperparameter (its shape channel). Lenient
    throughout -- an unresolvable reference is skipped so universe-building
    never raises on an unrelated node, and a node with no resolvable entry
    contributes nothing.

    NB the transition paradigm's ``continuation_ratio.segment`` emits the
    ``segment`` axis through a ``segment_axis`` hyperparameter that is *not* an
    anchor's output channel, so it is not captured here directly; ``segment``
    reaches the universe via the root-latent surface above (the ``profile_*``
    fields declare it). Making that producer's output axis a first-class generic
    surface is deferred with the broader anchor/segment reconciliation.
    """
    cpd = node.cpd
    if cpd is None:
        return set()
    entry = _resolve_entry(node)
    if entry is None:
        return set()
    out: set[str] = set()
    for decl in entry.parameter_schema.values():
        if decl.axes:
            try:
                out.update(resolve_axis_refs(cpd, entry, decl.axes))
            except ValueError:
                pass
    descriptor = entry.segmentation_anchor
    if descriptor is not None:
        try:
            out.add(
                resolved_axis_name(cpd, entry, descriptor.output_axis_hyperparameter)
            )
        except ValueError:
            pass
    # TODO(anchor/segment reconciliation): this root-latent `axes` surface is
    # currently load-bearing for `segment` in the transition paradigm, whose
    # true producer (continuation_ratio.segment's `segment_axis`) is not yet a
    # generic surface (see the NB in this function's docstring). Until it is,
    # a transition config only keeps `segment` in the universe because the
    # profile_* root latents happen to declare it -- a coincidence, not a
    # principled derivation. Make that producer first-class and revisit.
    if is_root_latent_constructor(entry):
        out.update(_root_latent_axis_names(cpd, entry))
    return out

def _axis_universe(config: GraphConfig, axes) -> set[str]:
    """The config's axis universe: declared axes plus CPD-generated ones."""
    universe = set(axes)
    for node in config.nodes:
        universe |= _node_generated_axes(node)
    return universe

def _validate_select_specs(config: GraphConfig, universe: set[str]) -> None:
    """Check every select-spec ``axis:`` names a real axis (decision 5).

    A select spec is any hyperparameter value that is a dict carrying an
    ``axis`` key (the constraint ``lower_spec`` / ``upper_spec`` shape). Its
    ``axis`` must lie in the universe; otherwise a loud, named error -- the
    clear desugar-time successor to ``_resolve_selectors``'s deep runtime raise
    (``core/structured_array.py``). Family-agnostic: keyed on the dict shape,
    not on the constraint family.
    """
    for node in config.nodes:
        if node.cpd is None:
            continue
        for key, value in node.cpd.hyperparameters.items():
            if isinstance(value, dict) and "axis" in value:
                axis = value["axis"]
                if axis not in universe:
                    raise ValueError(
                        f"node {node.id!r} hyperparameter {key!r} selects on "
                        f"`axis: {axis!r}`, which is not an axis of this config; "
                        f"valid axes are {sorted(universe)}"
                    )

def _validate_node_overrides(config: GraphConfig, universe: set[str]) -> None:
    """Check ``exclude_axes`` / ``include_axes`` on every node (decision 7).

    Each named axis must lie in the same universe as the select-spec check.

    The two lists are **not** mutually exclusive: ``exclude_axes`` subtracts from
    the default demographic complement and ``include_axes`` *augments* it (adds
    axes on top -- the M3b-ratified semantics, superseding M3a's shipped
    "replace"). Naming an axis in both is a contradiction (add it, drop it) and
    stays an error; the augment-vs-replace flip only changes what a lone
    ``include_axes`` means, which M3b's shape pass consumes.
    """
    for node in config.nodes:
        both = set(node.exclude_axes) & set(node.include_axes)
        if both:
            raise ValueError(
                f"node {node.id!r} lists {sorted(both)} in both `exclude_axes` "
                f"and `include_axes`; an axis cannot be both dropped from and "
                f"added to the default complement"
            )
        for field_name, axis_list in (
            ("exclude_axes", node.exclude_axes),
            ("include_axes", node.include_axes),
        ):
            for axis in axis_list:
                if axis not in universe:
                    raise ValueError(
                        f"node {node.id!r} `{field_name}` names {axis!r}, which is "
                        f"not an axis of this config; valid axes are "
                        f"{sorted(universe)}"
                    )

def _demanded_axes(node: NodeDef, entry: ConstructorEntry | None) -> tuple[str, ...]:
    """The structural axes a node's CPD *can't function without* (§5).

    "Demanded" is a property of the CPD contract, not of the node. The only
    first-class declaration of a node's own output axis today is a segmentation
    anchor's ``output_axis`` (the ``segment`` axis a ``segment``-role node
    emits); ``ParamDecl.axes`` declares what a node needs *of its parents*, and
    the ``axes`` hyperparameter is an author override, neither of which is a
    structural demand. So among the complement roles only ``segment`` demands an
    axis; ``indicator_latent`` / ``population`` demand none (their shape is
    entirely the free demographic part). An unresolvable anchor reference is
    treated as no demand rather than raising -- the loud check lives in build.
    """
    if entry is None or entry.segmentation_anchor is None:
        return ()
    try:
        return (
            resolved_axis_name(
                node.cpd, entry, entry.segmentation_anchor.output_axis_hyperparameter
            ),
        )
    except ValueError:
        return ()

def _indicator_stamp(config: GraphConfig, codes: Mapping[str, str | None]) -> GraphConfig:
    """Write ``codes`` onto their nodes, returning ``config`` itself if nothing moved."""
    new_nodes: list[NodeDef] = []
    changed = False
    for node in config.nodes:
        code = codes.get(node.id)
        if code == node.indicator:
            new_nodes.append(node)
            continue
        new_nodes.append(node.model_copy(update={"indicator": code}))
        changed = True
    if not changed:
        return config
    return config.model_copy(update={"nodes": new_nodes})

def _obs_entry_keys(entry: ObsEntryDef) -> dict[str, str]:
    """The identity fields ``entry`` actually names."""
    return {
        field: value
        for field in _OBS_KEY_FIELDS
        if (value := getattr(entry, field)) is not None
    }

def _obs_entry_matches(keys: Mapping[str, str], triple: Sequence[str]) -> bool:
    """Whether an entry naming ``keys`` speaks about ``triple``."""
    named = dict(zip(_OBS_KEY_FIELDS, triple))
    return all(named[field] == value for field, value in keys.items())

def _wire_population_edges(config: GraphConfig) -> GraphConfig:
    """Make the population node a parent of every grid that collapses a rate axis.

    A grid whose latent carries an axis the grid does not name aggregates over
    that axis (:func:`model.cpds.observations.grid._latent_at`), and a rate
    aggregates by population-weighted mean. The weights arrive as the grid's
    ``population`` binding -- an edge, so they are the *modeled* population
    node with its own priors, not fixed sheet numbers. The edge lands on the
    consumer rather than on the weighted latent: population is not being
    claimed as a cause of income, only as the measure the collapse averages
    over.

    Runs on the data path: ``populate_obs`` is what writes a grid's ``axes``,
    so a config desugared without observations has no grids to wire and this
    pass finds nothing. A count latent needs no weights (it collapses by
    summing), and the population node's own grid is skipped -- it would be its
    own parent. v4+ only.
    """
    if config.version < 4:
        return config

    pop_nodes = _population_pointer_nodes(config)
    if not pop_nodes:
        return config
    if len(pop_nodes) > 1:
        ids = ", ".join(repr(n.id) for n in pop_nodes)
        raise ValueError(
            "more than one node carries `special: [population]` "
            f"({ids}); the population pointer is unique"
        )
    pop = pop_nodes[0]

    def axes_of(node: NodeDef | None) -> tuple[str, ...]:
        if node is None or node.cpd is None:
            return ()
        return tuple(node.cpd.hyperparameters.get("axes") or ())

    by_id = {node.id: node for node in config.nodes}
    edges = list(config.edges)
    edge_pairs = {(e.parent, e.child) for e in edges}
    before = len(edges)

    for grid in config.nodes:
        if grid.cpd is None or grid.cpd.constructor != _GRID_OBS_CONSTRUCTOR:
            continue
        named = axes_of(grid)
        for parent_id, child_id in sorted(edge_pairs):
            if child_id != grid.id or parent_id == pop.id:
                continue
            latent = by_id.get(parent_id)
            if latent is None or not _is_rate_family(latent):
                continue
            if all(axis in named for axis in axes_of(latent)):
                continue
            _add_edge(edges, edge_pairs, pop.id, grid.id)

    if len(edges) == before:
        return config
    return config.model_copy(update={"edges": edges})

def axes_of(node: NodeDef | None) -> tuple[str, ...]:
    if node is None or node.cpd is None:
        return ()
    return tuple(node.cpd.hyperparameters.get("axes") or ())

def _resolve_data_ref(value: Any, data_resolver: DataResolver | None, what: str) -> Any:
    """Materialize a data-ref ``value`` via ``data_resolver``, or raise.

    ``value`` is a raw ``{from_data: ...}`` mapping or a :class:`DataRef`. With no
    resolver this raises :class:`UnresolvedDataRef` (the Tier-1 boundary); with
    one it coerces to a :class:`DataRef` and returns the resolver's output.
    """
    if data_resolver is None:
        raise UnresolvedDataRef(
            f"{what} is data-derived ({value}); resolve it in the "
            "data-binding step (inject a data_resolver)"
        )
    ref = value if isinstance(value, DataRef) else DataRef.model_validate(value)
    return data_resolver(ref)

def is_data_ref(value: Any) -> bool:
    """True if ``value`` is a raw ``{from_data: ...}`` mapping or a DataRef."""
    return isinstance(value, DataRef) or (
        isinstance(value, dict) and DATA_REF_KEY in value
    )

def to_basis_spec(self) -> BasisSpec:
    return BasisSpec(
        name=self.name,
        family=self.family,
        knots=tuple(self.knots),
        grid=tuple(self.grid),
        boundary=self.boundary,
    )

def to_axis_meta(
    self, name: str, *, data_resolver: DataResolver | None = None
) -> AxisMeta:
    if is_data_ref(self.levels):
        levels = _resolve_data_ref(
            self.levels, data_resolver, f"axis {name!r} levels"
        )
    else:
        levels = self.levels
    return AxisMeta(
        name=name,
        levels=tuple(levels),
        kind=self.kind,
        basis=self.basis.to_basis_spec() if self.basis else None,
        axis_role=self.axis_role,
    )

def to_indicator_meta(self) -> IndicatorMeta:
    return IndicatorMeta(
        indicator=self.indicator, family=self.family, unit=self.unit
    )

def as_hyperparameters(self) -> dict[str, float]:
    out: dict[str, float] = {}
    if self.default_precision is not None:
        out["default_precision"] = self.default_precision
    if self.default_concentration is not None:
        out["default_concentration"] = self.default_concentration
    return out

def family_obs_override(self, family: str) -> dict[str, float]:
    """Declared hyperparameter overrides for one obs CPD family, if any."""
    tpl = self.families.get(family)
    if tpl is None:
        return {}
    return tpl.as_hyperparameters()

def resolved_axis_breakdown(self) -> dict[str, frozenset[str]] | None:
    """Per-axis indicator breakdown when declared; ``None`` when absent.

    ``gender_breakdown`` is accepted as a legacy alias that fills
    ``axis_breakdown["gender"]`` when that key is not already set.
    """
    if self.axis_breakdown is None and self.gender_breakdown is None:
        return None
    out: dict[str, frozenset[str]] = {}
    if self.axis_breakdown is not None:
        out = {
            str(axis): frozenset(str(i) for i in indicators)
            for axis, indicators in self.axis_breakdown.items()
        }
    if self.gender_breakdown is not None and "gender" not in out:
        out["gender"] = frozenset(str(i) for i in self.gender_breakdown)
    return out

@model_validator(mode="after")
def _cpd_is_override_shaped(self) -> "PriorDef":
    """A prior override cannot rebind roles or steer v1 parent synthesis.

    ``parameter_bindings`` and ``parents`` are meaningful only on a
    first-class node cpd; in a ``priors.<role>.cpd`` fragment they have no
    referent (the emitted node's role is fixed by the walk, and v1 ``parents``
    steering does not apply under the v2 ``priors:`` surface). Reject them
    loudly rather than silently drop, so a mistaken author sees the error.
    """
    if self.cpd is None:
        return self
    for field_name in ("parameter_bindings", "parents"):
        if getattr(self.cpd, field_name):
            raise ValueError(
                f"`priors.<role>.cpd.{field_name}` is not allowed: a prior "
                f"override fragment steers only distribution / hyperparameters "
                f"(and nested `priors`), not role bindings or parent synthesis"
            )
    return self

def to_cpd_spec(
    self,
    axis_registry: dict[str, AxisMeta],
    *,
    data_resolver: DataResolver | None = None,
) -> CpdSpec:
    """Build the ``core`` ``CpdSpec``, resolving axis refs by name.

    ``axis_registry`` holds the *already resolved* concrete axes. The ``axes``
    hyperparameter (a list of names) is mapped through it to a tuple of
    ``AxisMeta``. Any other :class:`DataRef`-valued hyperparameter is
    materialized via ``data_resolver`` if one is injected, else raises
    :class:`UnresolvedDataRef` -- those belong to the data-binding step.
    """
    hp: dict[str, Any] = {}
    for key, value in self.hyperparameters.items():
        if is_data_ref(value):
            hp[key] = _resolve_data_ref(
                value, data_resolver, f"hyperparameter {key!r}"
            )
        elif key == "axes" and isinstance(value, Mapping):
            # A grid states its own levels, and they are a subset of the
            # registry's -- only the levels some row asserts (12:42). So there
            # is nothing to resolve, and resolving would widen the grid back
            # to the declared axis.
            hp[key] = {axis: tuple(levels) for axis, levels in value.items()}
        elif key == "axes":
            hp[key] = tuple(_resolve_axis(name, axis_registry) for name in value)
        elif key == "entries":
            # A bundled prior's entries carry per-entry `axes` as name lists
            # (desugar works in name space); resolve each to AxisMeta here, the
            # only layer holding the axis registry. Non-`axes` entry fields
            # (consumer_id, role) pass through untouched.
            hp[key] = tuple(
                {
                    **entry,
                    "axes": tuple(
                        _resolve_axis(name, axis_registry)
                        for name in entry["axes"]
                    ),
                }
                for entry in value
            )
        else:
            hp[key] = _plain_hyperparameter(
                value, data_resolver, f"hyperparameter {key!r}"
            )
    return CpdSpec(
        family=self.family,
        constructor=self.constructor,
        hyperparameters=hp,
        parameter_bindings={
            role: tuple(parents) for role, parents in self.parameter_bindings.items()
        },
    )

@model_validator(mode="after")
def _cpd_has_family(self) -> "ObsEntryDef":
    named = ", ".join(
        f"{k}={v!r}"
        for k, v in (
            ("indicator", self.indicator),
            ("source", self.source),
            ("unit", self.unit),
        )
        if v
    )
    _require_cpd_family(
        self.cpd,
        where=f"`obs` entry ({named})" if named else "an `obs` entry",
    )
    return self

def resolve(self, base: NodeRoleSpec) -> NodeRoleSpec:
    """This entry's stated answers, over ``base``'s."""
    stated = {
        field: value
        for field, value in (
            ("axes", self.axes),
            ("indicator", self.indicator),
            ("observable", self.observable),
            ("unique", self.unique),
            ("special", tuple(self.special) if self.special is not None else None),
        )
        if value is not None
    }
    return replace(base, **stated)

@field_validator("parents", mode="before")
@classmethod
def _coerce_parent_refs(cls, parents: Any) -> Any:
    """Accept the bare-string ref form (``- theta_bias``)."""
    if not isinstance(parents, (list, tuple)):
        return parents
    return [{"id": p} if isinstance(p, str) else p for p in parents]

@field_validator("obs", mode="before")
@classmethod
def _coerce_obs_entries(cls, obs: Any) -> Any:
    """Accept the single-mapping form (``obs: {cpd: ...}``) as one entry.

    The list is the general shape -- a latent may be observed by several
    sources -- but a lone observation is the common case and the only one
    ≤v3 can spell, so the mapping form is kept rather than migrated. An empty
    list normalizes to ``None``: "observed by nothing" and "no obs block" are
    the same fact, and collapsing them here means downstream passes have one
    absence to test instead of two.
    """
    if isinstance(obs, dict):
        return [obs]
    if isinstance(obs, (list, tuple)) and not obs:
        return None
    return obs

@model_validator(mode="after")
def _cpd_has_family(self) -> "NodeDef":
    _require_cpd_family(self.cpd, where=f"node {self.id!r}")
    return self

@classmethod
def from_pair(cls, pair: Any) -> "EdgeDef":
    if isinstance(pair, (list, tuple)) and len(pair) == 2:
        return cls(parent=pair[0], child=pair[1])
    if isinstance(pair, dict):
        return cls(**pair)
    raise ValueError(f"edge must be a [parent, child] pair or mapping; got {pair!r}")

@field_validator("version")
@classmethod
def _check_version_supported(cls, version: int) -> int:
    """Reject unknown schema versions loudly, before any building happens."""
    if version not in SUPPORTED_VERSIONS:
        raise ValueError(
            f"unsupported config version {version!r}; supported versions "
            f"are {SUPPORTED_VERSIONS} (omit `version` for the latest, "
            f"{LATEST_VERSION})"
        )
    return version

@model_validator(mode="after")
def _check_node_role_assignments(self) -> "GraphConfig":
    """Every hand-written ``role:`` is a role, and unique roles are unique.

    Validates what the *author* wrote, not what ``resolve_role`` will return:
    a role arriving from the constructor's ``default_role`` is registry-side
    knowledge this module cannot see (the registry may not even be populated
    yet), and every such role is a built-in by construction. A typo can only
    enter here.

    Without this, an unrecognized role was the cheapest mistake to make and the
    most expensive to notice: every set-membership test quietly answers False,
    so the node gets no complement axes, no observations, and no diagnostic.
    """
    roles = self.resolved_node_roles()
    holders: dict[str, str] = {}
    for node in self.nodes:
        if node.role is None:
            continue
        spec = roles.get(node.role)
        if spec is None:
            known = ", ".join(sorted(roles))
            raise ValueError(
                f"node {node.id!r} declares unknown role {node.role!r}; "
                f"declare it under `node_roles:` or use one of {known}"
            )
        if spec.unique:
            held = holders.get(node.role)
            if held is not None:
                raise ValueError(
                    f"role {node.role!r} is `unique`, but both {held!r} and "
                    f"{node.id!r} declare it"
                )
            holders[node.role] = str(node.id)
    return self

@model_validator(mode="after")
def _check_sugar_requires_v2(self) -> "GraphConfig":
    """Reject v2 sugar under ``version: 1`` -- v1 is the flat form by
    definition, and the v1 pass-through gate would otherwise silently
    ignore the author's ``parents:``/``obs:`` intent."""
    if self.version != 1:
        return self
    if self.node_cap is not None:
        raise ValueError(
            "`node_cap:` steers the desugaring walk, which requires "
            "`version: 2`; this config pins `version: 1` (the flat form)"
        )
    for name, axis in self.axes.items():
        field = None
        if axis.demographic_disagg:
            field = "demographic_disagg"
        elif axis.subdiv_of is not None:
            field = "subdiv_of"
        elif axis.membership is not None:
            field = "membership"
        elif isinstance(axis.levels, list) and any(
            is_range_token(level) for level in axis.levels
        ):
            field = "levels (range shorthand)"
        if field is not None:
            raise ValueError(
                f"axis {name!r} uses the `{field}:` sugar, which requires "
                f"`version: 2`; this config pins `version: 1` (the flat form)"
            )
    for node in self.nodes:
        field = None
        if node.parents:
            field = "parents"
        elif node.role is not None:
            field = "role"
        elif node.obs is not None:
            field = "obs"
        elif node.exclude_axes:
            field = "exclude_axes"
        elif node.include_axes:
            field = "include_axes"
        elif node.cpd is not None and (
            node.cpd.priors or node.cpd.autoconstruct_priors is not None
        ):
            field = "cpd.priors" if node.cpd.priors else "cpd.autoconstruct_priors"
        if field is not None:
            raise ValueError(
                f"node {node.id!r} uses the `{field}:` sugar, which requires "
                f"`version: 2`; this config pins `version: 1` (the flat form)"
            )
    return self

@model_validator(mode="after")
def _check_prior_include_axes_requires_v3(self) -> "GraphConfig":
    """Reject ``priors.<role>.include_axes`` below ``version: 3``.

    v3 replaces the v1/v2 "B" inference (``infer_disaggregation_axes``) with
    this declaration; under v1/v2 the inference path runs and the field would
    be a silent no-op, so name it loudly instead."""
    if self.version >= 3:
        return self

    def _scan(priors: dict, node_id: str) -> None:
        # A role's value is one node block, or -- for a fanned-out role -- a
        # mapping of key -> node block. Both shapes recurse the same way.
        for role, value in priors.items():
            blocks = (
                [(role, value)]
                if isinstance(value, PriorDef)
                else [(f"{role}.{key}", block) for key, block in value.items()]
            )
            for where, pdef in blocks:
                if pdef.include_axes:
                    raise ValueError(
                        f"node {node_id!r} uses `priors.{where}.include_axes:`, "
                        f"which requires `version: 3`; this config pins "
                        f"`version: {self.version}` (disaggregation is inferred, "
                        f"not declared)"
                    )
                if pdef.cpd is not None and pdef.cpd.priors:
                    _scan(pdef.cpd.priors, node_id)

    for node in self.nodes:
        if node.cpd is not None and node.cpd.priors:
            _scan(node.cpd.priors, node.id)
    return self

def _scan(priors: dict, node_id: str) -> None:
    # A role's value is one node block, or -- for a fanned-out role -- a
    # mapping of key -> node block. Both shapes recurse the same way.
    for role, value in priors.items():
        blocks = (
            [(role, value)]
            if isinstance(value, PriorDef)
            else [(f"{role}.{key}", block) for key, block in value.items()]
        )
        for where, pdef in blocks:
            if pdef.include_axes:
                raise ValueError(
                    f"node {node_id!r} uses `priors.{where}.include_axes:`, "
                    f"which requires `version: 3`; this config pins "
                    f"`version: {self.version}` (disaggregation is inferred, "
                    f"not declared)"
                )
            if pdef.cpd is not None and pdef.cpd.priors:
                _scan(pdef.cpd.priors, node_id)

@model_validator(mode="after")
def _check_aka_requires_v4(self) -> "GraphConfig":
    """Reject ``aka:`` below ``version: 4``, for ``indicator:``'s reason.

    There is no <=v3 spelling to fall back on -- ``aka`` is new in v4 -- and no
    <=v3 consumer would read it, so accepting it there would silently drop
    sheet codes the author asked for.
    """
    if self.version >= 4:
        return self
    offenders = [node.id for node in self.nodes if node.aka]
    if not offenders:
        return self
    raise ValueError(
        f"node(s) {sorted(offenders)} declare `aka:`, which requires "
        f"`version: 4`; this config pins `version: {self.version}`"
    )

@model_validator(mode="after")
def _check_no_two_nodes_claim_one_indicator_code(self) -> "GraphConfig":
    """Refuse a sheet code claimed by two nodes, across ``indicator`` and ``aka``.

    A code identifies *rows*, so two claimants leave the loader with no way to
    say which node a row belongs to -- and by the time the sheet is open the
    only available repair is to guess. Reported here, before any data is read.

    Only *declared* codes are checked. The node-id fallback is desugar's, and a
    collision between a declared code and some other node's id is a different
    (and today harmless) fault; catching it needs the resolved answer, so it
    would belong in ``resolve_own_indicators``, not in a pre-desugar validator.
    """
    claimants: dict[str, str] = {}
    for node in self.nodes:
        for code in ((node.indicator,) if node.indicator else ()) + node.aka:
            other = claimants.setdefault(code, node.id)
            if other != node.id:
                raise ValueError(
                    f"data-sheet code {code!r} is claimed by both node "
                    f"{other!r} and node {node.id!r} (as `indicator` or `aka`); "
                    "a code names one node's rows, so drop or rename one"
                )
    return self

@model_validator(mode="after")
def _check_parents_steering_is_v1_only(self) -> "GraphConfig":
    """Reject ``cpd.parents`` steering under v2 -- the v2 surface for the
    same intent is ``priors:`` (which the desugaring walk consumes), and
    letting both through would leave two competing steering vocabularies
    on one node."""
    if self.version == 1:
        return self
    for node in self.nodes:
        spec_sites = []
        if node.cpd is not None:
            spec_sites.append(("cpd", node.cpd))
        for i, entry in enumerate(node.obs or []):
            spec_sites.append((f"obs[{i}].cpd", entry.cpd))
        for where, spec in spec_sites:
            if spec.parents:
                raise ValueError(
                    f"node {node.id!r} writes `{where}.parents:` steering, "
                    f"which is the `version: 1` surface; under `version: 2` "
                    f"write the same intent as a `priors:` block"
                )
    return self

@field_validator("edges", mode="before")
@classmethod
def _coerce_edge_pairs(cls, edges: Any) -> Any:
    """Accept the ``[parent, child]`` list form authored in YAML."""
    if not isinstance(edges, (list, tuple)):
        return edges
    return [
        e if isinstance(e, (EdgeDef, dict)) else EdgeDef.from_pair(e)
        for e in edges
    ]

def resolve_axes(
    self, *, data_resolver: DataResolver | None = None
) -> dict[str, AxisMeta]:
    """Resolve the axis registry to concrete :class:`AxisMeta`.

    Without a ``data_resolver`` only the concrete axes resolve; data-derived
    axes (e.g. ``country``) are skipped for a later binding step. With one,
    every axis resolves -- the data-derived levels are materialized through
    it -- so the returned registry is complete for node conversion.
    """
    out: dict[str, AxisMeta] = {}
    for name, axis in self.axes.items():
        if is_data_ref(axis.levels) and data_resolver is None:
            continue
        out[name] = axis.to_axis_meta(name, data_resolver=data_resolver)
    return out

def _resolve_axis(name: str, registry: dict[str, AxisMeta]) -> AxisMeta:
    try:
        return registry[name]
    except KeyError:
        raise UnresolvedDataRef(
            f"axis {name!r} is not resolved (likely data-derived); "
            "the data-binding step must supply it before this node converts"
        ) from None

def register_pipeline_cpds(*, clear: bool = True) -> None:
    """Register CPD constructors for ``compile_model`` / ``run_map``.

    Clears the global registry first by default so repeated CLI invocations in
    one process do not double-register.
    """
    if clear:
        _clear_registry()
    for module in _DEFAULT_MODULES:
        module.register()
    register_observations()

@property
def n_countries(self) -> int:
    return len(self.countries)

@property
def n_genders(self) -> int:
    return len(self.genders)

@property
def country_axis(self) -> AxisMeta:
    return AxisMeta(name="country", levels=self.countries, kind="categorical")

@property
def gender_axis(self) -> AxisMeta:
    return AxisMeta(name="gender", levels=self.genders, kind="categorical")

def col(code: str, source: str | None = None, scale: float = 1.0) -> np.ndarray:
    rows = _ttt(d, code, source)
    if tuple(rows.country_iso3) != countries:
        raise ValueError(
            f"{code}: expected one T/T/T row per country in {countries}; "
            f"got {tuple(rows.country_iso3)}"
        )
    return rows.value.to_numpy(dtype=float) * scale

def demo_observations(panel: Panel) -> Observations:
    """The 2024 evidence, each value reshaped to its observation site's cell shape.

    Genderless sites (income after the gender aggregation, coverage) take
    ``(country, year)``; gendered sites (population, the two manifestations)
    take ``(country, year, gender)``.

    The six constraint sites are observed at **0** -- the synthetic
    "no violation seen" evidence that turns each Bernoulli child into a soft
    penalty (log P(X=0) = log(1 - p)). Their cell shapes follow the violation:
    every constraint touching the gendered shares or manifestation means
    inherits the gendered cells; the income constraint takes the genderless
    (country, year) cells (gender is sliced away).
    """
    def cell(a: np.ndarray) -> jnp.ndarray:
        return jnp.asarray(a.reshape(panel.n_countries, 1))

    def cell_g(a: np.ndarray) -> jnp.ndarray:
        return jnp.asarray(a.reshape(panel.n_countries, 1, panel.n_genders))

    def clip(a: np.ndarray) -> np.ndarray:
        # Beta-observed fractions clipped just inside (0, 1) -- see _OBS_FRACTION_EPS.
        return np.clip(a, _OBS_FRACTION_EPS, 1.0 - _OBS_FRACTION_EPS)

    return Observations(
        by_site={
            "income_obs": cell(panel.income),
            "pop_obs": cell_g(panel.population),
            "cov_3g_obs": cell(clip(panel.cov_3g)),
            "cov_4g_obs": cell(clip(panel.cov_4g)),
            "mobinet_obs": cell_g(clip(panel.mobinet)),
            "smartphone_obs": cell_g(clip(panel.smartphone)),
            "constraint_3g": jnp.zeros((panel.n_countries, 1, panel.n_genders)),
            "constraint_4g": jnp.zeros((panel.n_countries, 1, panel.n_genders)),
            "constraint_income": jnp.zeros((panel.n_countries, 1)),
            "constraint_smartphone": jnp.zeros(
                (panel.n_countries, 1, panel.n_genders)
            ),
            "constraint_mobinet_floor": jnp.zeros(
                (panel.n_countries, 1, panel.n_genders)
            ),
            "constraint_mobinet_ceiling": jnp.zeros(
                (panel.n_countries, 1, panel.n_genders)
            ),
        }
    )

def clip(a: np.ndarray) -> np.ndarray:
    # Beta-observed fractions clipped just inside (0, 1) -- see _OBS_FRACTION_EPS.
    return np.clip(a, _OBS_FRACTION_EPS, 1.0 - _OBS_FRACTION_EPS)

def level_of(self, row: pd.Series) -> Any:
    """The level this row asserts, or ``_UNASSERTED`` if it asserts none."""
    raw = []
    for column in self.columns:
        if column not in row.index:
            return _UNASSERTED
        raw.append(row[column])
    if any(str(v) in _TOTAL_LEVELS for v in raw):
        return _UNASSERTED
    return self.recode(*raw)

def sort_of(self, column: str) -> str | None:
    """This column's sort, or ``None`` if the spec does not name it."""
    for sort in ("value", "indicator", "unit", "source"):
        if getattr(self, sort) == column:
            return sort
    for axis, entry in self.axes.items():
        if column in entry.columns:
            return "date" if axis == self.date_axis else "axis"
    if column in self.metadata:
        return "metadata"
    return None

def column_for(self, concept: str) -> str | None:
    """The single column carrying ``concept``, if there is exactly one."""
    singles = {
        "value": self.value,
        "indicator": self.indicator,
        "unit": self.unit,
        "source": self.source,
    }
    if concept in singles:
        return singles[concept]
    entry = self.axes.get(concept)
    if entry is not None and len(entry.columns) == 1:
        return entry.columns[0]
    return concept if concept in self.metadata else None

@property
def axis_columns(self) -> tuple[str, ...]:
    return tuple(c for entry in self.axes.values() for c in entry.columns)

def with_axis(
    self, axis: str, columns: tuple[str, ...], recode: Any = str
) -> "SheetSpec":
    """This spec plus one more axis."""
    return replace(
        self,
        axes=MappingProxyType(
            {**self.axes, axis: AxisColumns(columns=columns, recode=recode)}
        ),
    )

def _fold_level(level: Any) -> str:
    """The form two spellings of one level agree on. The only case rule."""
    return str(level).casefold()

def __post_init__(self) -> None:
    for axis, levels in self.axis_levels.items():
        folded: dict[str, Any] = {}
        for level in levels:
            clash = folded.setdefault(_fold_level(level), level)
            if clash is not level:
                raise ValueError(
                    f"axis {axis!r} declares {clash!r} and {level!r}, which "
                    f"differ only in case; a level read off the sheet has no "
                    f"one canonical spelling"
                )

def label(self, axis: str) -> str:
    """The name this axis wears on a loaded record."""
    return self.axis_aliases.get(axis, axis)

def canonical(self, label: str, level: Any) -> Any:
    """``level`` under the config's spelling, if the config declares one.

    The one place a level's spelling is decided, so every reading over the store
    agrees on it. A value matching no declared level passes through unchanged:
    it stays the undeclared level it is, dropped later by the gate with a
    warning naming it, rather than becoming an error at the seam.
    """
    declared = self.axis_levels.get(label)
    if not declared:
        return level
    by_fold = {_fold_level(d): d for d in declared}
    return by_fold.get(_fold_level(level), level)

def _levels_source(axis: Any) -> str | None:
    """The resolver name this axis's levels come from, if they come from data."""
    levels = getattr(axis, "levels", None)
    if isinstance(levels, Mapping):
        return levels.get("from_data")
    return getattr(levels, "source", None)

def loader_spec_from_config(config: Any, sheet: SheetSpec | None = None) -> LoaderSpec:
    """Collect the config's demographic axis names and package them with the sheet.

    Called before the load, by a caller; the loader never reads the config.

    The geography alias is read off the config rather than assumed: the axis whose
    levels come from ``country.levels`` is the config's name for the sheet's
    ``geo_axis``. Without it a loaded row labels its geography ``geo_finest`` and
    a config axis named ``country`` never matches it.

    Declared levels come along for the same reason: the config's spelling of a level
    is the one the load hands to every reading. Only axes with a concrete level list
    contribute -- an axis whose levels come from the data has no spelling to declare,
    so its levels stay as the sheet writes them.
    """
    axes = getattr(config, "axes", None) or {}
    sheet = sheet if sheet is not None else NATIONAL_LONG_SPEC
    geo = [n for n, ax in axes.items() if _levels_source(ax) == _GEO_LEVELS_SOURCE]
    return LoaderSpec(
        sheet=sheet,
        axis_levels=MappingProxyType(
            {
                name: tuple(ax.levels)
                for name, ax in axes.items()
                if isinstance(getattr(ax, "levels", None), (list, tuple))
            }
        ),
        config_axes=tuple(
            name
            for name, ax in axes.items()
            if getattr(ax, "demographic_disagg", False)
        ),
        axis_aliases=MappingProxyType(
            {sheet.geo_axis: geo[0]} if sheet.geo_axis and len(geo) == 1 else {}
        ),
    )

def _as_loader_spec(spec: LoaderSpec | SheetSpec | None) -> LoaderSpec:
    if spec is None:
        return LoaderSpec(sheet=NATIONAL_LONG_SPEC)
    if isinstance(spec, LoaderSpec):
        return spec
    return LoaderSpec(sheet=spec)

@property
def site(self) -> ObservedSite:
    """This bundle with its cell layout set aside."""
    return ObservedSite(
        site_id=self.site_id, family=self.family, values=self.values
    )

def cpd_hyperparameters(
    self, **extra: Any
) -> dict[str, Any]:
    """Hyperparameters dict for ``CpdSpec`` on this bundle node.

    Cell-paradigm-specific, and knowingly so: ``cells`` is the ≤v3 Type-III
    hyperparameter. A grid node needs no analogue of this method.
    """
    return {"cells": self.cells, **extra}

@property
def triple(self) -> tuple[str, str, str]:
    return (self.indicator, self.source, self.unit)

def level(self, axis: str) -> Any:
    """This row's level on ``axis``, or ``_UNASSERTED``.

    The identity fields answer to their own names, so a grid can request
    ``indicator``/``source``/``unit`` as length-1 axes [12:42]. The small end
    of folding the triple into ``levels`` [10:35]; until that lands, this is
    the one place that knows they are readable as axes.
    """
    if axis in _IDENTITY_AXES:
        return getattr(self, axis)
    return self.levels.get(axis, _UNASSERTED)

@property
def triples(self) -> tuple[tuple[str, str, str], ...]:
    return tuple(self._levels)

def levels(self, triple: Sequence[str]) -> dict[str, tuple[Any, ...]]:
    """Axis -> observed levels for one triple; ``{}`` if it is not held.

    An axis no row asserts is absent, not present-and-empty.
    """
    return dict(self._levels.get(tuple(triple), {}))

def survey(self) -> ObservationSurvey:
    """Index the store by triple, reporting the levels observed on each axis."""
    levels: dict[tuple[str, str, str], dict[str, list[Any]]] = {}
    for rec in self.records:
        by_axis = levels.setdefault(rec.triple, {})
        for axis, level in rec.levels.items():
            seen = by_axis.setdefault(axis, [])
            if level not in seen:
                seen.append(level)
    return ObservationSurvey(
        _levels={
            triple: {axis: tuple(v) for axis, v in by_axis.items()}
            for triple, by_axis in levels.items()
        }
    )

def bundle(self, site_id: str) -> ObservationCellBundle:
    for b in self.cell_bundles:
        if b.site_id == site_id:
            return b
    raise KeyError(f"no bundle with site_id {site_id!r}")

def default_integrated_data_path(
    filename: str = "national_long_27countries_20260724.xlsx",
) -> Path:
    """Return the canonical path to a file under ``data/03_Integrated_Data/``."""
    return DEFAULT_INTEGRATED_DATA_DIR / filename

def _normalize_value(unit: str, raw: float) -> float:
    if unit in _PCT_UNITS:
        v = float(raw) / 100.0
        # TODO: When we settle on the observation distributions we want to use,
        # remove this clipping logic. Clipping for use with beta works for now,
        # but eventually we'll want a distribution whose support contains our
        # actual observations.
        return float(np.clip(v, 1e-6, 1.0 - 1e-6))
    return float(raw)

def row_metadata(
    row: pd.Series, spec: LoaderSpec | SheetSpec | None = None
) -> dict[str, Any]:
    """The kept-but-not-keying columns of one row [10:53]."""
    sheet = _as_loader_spec(spec).sheet
    return {c: row[c] for c in sheet.metadata if c in row.index}

def _select(
    out: pd.DataFrame, column: str, allowed: Sequence[Any]
) -> pd.DataFrame:
    """Keep rows whose ``column`` is in ``allowed``. An absent column errors [10:39]."""
    if column not in out.columns:
        raise KeyError(
            f"filter names column {column!r}, which the frame does not have; "
            f"it has {sorted(map(str, out.columns))}"
        )
    return out[out[column].isin(list(allowed))]

def _apply_filter(
    df: pd.DataFrame, flt: ObservationLoadFilter, spec: SheetSpec
) -> pd.DataFrame:
    out = df
    for field, concept in _NAMED_PREDICATES:
        allowed = getattr(flt, field)
        if not allowed:
            continue
        column = spec.column_for(concept)
        if column is None:
            raise SheetShapeError(
                f"filter field {field!r} needs a {concept!r} column, which the "
                f"spec does not name"
            )
        out = _select(out, column, allowed)
    for column, allowed in flt.columns.items():
        out = _select(out, str(column), allowed)
    if flt.year_min is not None or flt.year_max is not None:
        year_column = spec.column_for(spec.date_axis) if spec.date_axis else None
        if year_column is None:
            raise SheetShapeError("year window needs a date column")
        if flt.year_min is not None:
            out = out[out[year_column] >= flt.year_min]
        if flt.year_max is not None:
            out = out[out[year_column] <= flt.year_max]
    if flt.source_by_indicator:
        indicator_column = spec.column_for("indicator")
        source_column = spec.column_for("source")
        if indicator_column is None or source_column is None:
            raise SheetShapeError(
                "source_by_indicator needs indicator and source columns"
            )
        keep = pd.Series(True, index=out.index)
        for indicator, source in flt.source_by_indicator.items():
            keep &= ~(
                (out[indicator_column] == indicator)
                & (out[source_column] != source)
            )
        out = out[keep]
    return out

def _records_from_dataframe(
    df: pd.DataFrame, spec: LoaderSpec
) -> tuple[ObservationRecord, ...]:
    """One record per row, whatever its unit.

    ``_UNIT_TO_CELL_BUNDLE`` picks a *family*, which only the cell reading needs, so a
    unit it does not map still reaches the store.
    """
    records: list[ObservationRecord] = []
    for _, row in df.iterrows():
        identity = row_identity(row, spec)
        records.append(
            ObservationRecord(
                indicator=identity["indicator"],
                source=identity["source"],
                unit=identity["unit"],
                levels=row_axis_levels(row, spec),
                value=_normalize_value(
                    identity["unit"], float(row[spec.sheet.value])
                ),
                metadata=row_metadata(row, spec),
            )
        )
    return tuple(records)

def load_graph_config(path: str | Path) -> GraphConfig:
    """Load and validate a graph YAML file."""
    config_path = Path(path)
    with config_path.open() as f:
        raw = YAML().load(f)
    return GraphConfig.model_validate(raw)

def unit_cell_bundles_from_config(config: GraphConfig) -> dict[str, tuple[str, str]] | None:
    """``unit -> (family, site)`` overrides from config, or ``None`` if absent."""
    if config.observation_defaults is None:
        return None
    bundles = config.observation_defaults.to_unit_cell_bundles()
    return bundles or None

def observation_load_filter_for_config(
    config: GraphConfig,
    flt: ObservationLoadFilter | None = None,
) -> ObservationLoadFilter:
    """Merge ``observation_defaults.axis_breakdown`` into a loader filter.

    Legacy ``gender_breakdown`` is accepted via
    :meth:`ObservationDefaultsDef.resolved_axis_breakdown`.
    """
    base = flt or ObservationLoadFilter()
    if config.observation_defaults is None:
        return base
    updates: dict[str, Any] = {}
    axis_breakdown = config.observation_defaults.resolved_axis_breakdown()
    if axis_breakdown is not None:
        updates["axis_breakdown"] = axis_breakdown
    if config.observation_defaults.source_by_indicator:
        from types import MappingProxyType

        updates["source_by_indicator"] = MappingProxyType(
            dict(config.observation_defaults.source_by_indicator)
        )
    if not updates:
        return base
    return ObservationLoadFilter(**{**base.__dict__, **updates})

def build_graph_from_config(
    config: GraphConfig,
    loaded: LoadedObservations,
) -> BayesGraph:
    """Build a graph, choosing auto-attach vs explicit obs from the config shape.

    <=v3 only: on v4 the two routes are not alternatives, so ``loaded`` always goes
    through and each latent's own ``autoconstruct_obs`` decides whether desugar
    synthesizes an observation for it.
    """
    resolver = make_observation_resolver(loaded)
    if config.version < 4 and has_declared_observation_nodes(config):
        return build_graph(config, data_resolver=resolver)
    return build_graph(config, loaded, data_resolver=resolver)

def driver_match_candidates(node_id: str) -> tuple[str, ...]:
    """The keys ``node_id`` may be matched by, most faithful first.

    ``('income_z', 'income')`` for a standardizer; ``('income',)`` otherwise. The
    caller tries each against its own criterion in order, so the honest key always
    wins and the bridge only fires when nothing else does.
    """
    if node_id.endswith(_STANDARDIZER_SUFFIX) and len(node_id) > len(
        _STANDARDIZER_SUFFIX
    ):
        return (node_id, node_id[: -len(_STANDARDIZER_SUFFIX)])
    return (node_id,)

def _as_axis_tuple(axes_spec: Any) -> tuple[AxisMeta, ...]:
    """Normalize an entry's ``axes`` hyperparameter to ``tuple[AxisMeta, ...]``."""
    if isinstance(axes_spec, AxisMeta):
        return (axes_spec,)
    axes = tuple(axes_spec)
    if not axes:
        raise ValueError("bundled prior entry axes must be non-empty")
    if not all(isinstance(a, AxisMeta) for a in axes):
        raise TypeError(
            "bundled prior entry axes must be AxisMeta instances, "
            f"got {[type(a).__name__ for a in axes]}"
        )
    return axes

def _entry_specs(
    hyperparameters: Mapping[str, Any],
) -> tuple[tuple[str, str, tuple[AxisMeta, ...]], ...]:
    """Parse ``entries`` → ``((consumer_id, role, axes), ...)``."""
    raw = hyperparameters.get("entries")
    if not raw:
        raise ValueError("normal.bundled requires a non-empty 'entries' hyperparameter")
    out: list[tuple[str, str, tuple[AxisMeta, ...]]] = []
    for i, entry in enumerate(raw):
        try:
            consumer_id = str(entry["consumer_id"])
            role = str(entry["role"])
            axes = _as_axis_tuple(entry["axes"])
        except (KeyError, TypeError) as exc:
            raise ValueError(
                f"normal.bundled entries[{i}] must map consumer_id/role/axes "
                f"({exc})"
            ) from exc
        out.append((consumer_id, role, axes))
    return tuple(out)

def _labels_and_n_cells(
    specs: tuple[tuple[str, str, tuple[AxisMeta, ...]], ...],
) -> tuple[tuple[BundleCellLabel, ...], tuple[int, ...]]:
    labels: list[BundleCellLabel] = []
    n_cells: list[int] = []
    for consumer_id, role, axes in specs:
        lab = expand_bundle_entry_labels(
            consumer_id=consumer_id, role=role, entry_axes=axes
        )
        labels.extend(lab)
        n_cells.append(len(lab))
    return tuple(labels), tuple(n_cells)

def _flat_scale_from_entry_sigmas(
    entry_sigmas: jnp.ndarray,
    n_cells: tuple[int, ...],
) -> jnp.ndarray:
    """Broadcast per-entry σ (length n_entries) onto each entry's cells."""
    entry_sigmas = jnp.asarray(entry_sigmas).reshape(-1)
    if entry_sigmas.shape[0] != len(n_cells):
        raise ValueError(
            f"scale parent length {entry_sigmas.shape[0]} != n_entries "
            f"{len(n_cells)}"
        )
    chunks = [
        jnp.broadcast_to(entry_sigmas[i], (n,))
        for i, n in enumerate(n_cells)
    ]
    return jnp.concatenate(chunks)

def _flat_cell_hyperparameter(
    value: Any, n_cells: tuple[int, ...], name: str
) -> jnp.ndarray:
    """A ``bundle_partitioned`` hyperparameter as a flat per-cell vector.

    Three accepted shapes, in the order the pipeline produces them:

    - **scalar** -- one value for the whole bundle, broadcast to every cell;
    - **length n_entries** -- one value per effect-group entry, broadcast onto
      that entry's cells. This is what the desugar walk emits, and what makes a
      coalesced bundle able to carry each consumer's own declaration: entries
      concatenate in a fixed order and these ride that same order;
    - **length n_flat** -- already cell-aligned (hand-authored full precision).

    Any other length is a loud error naming the two it could have been, because
    that alignment *is* the contract: a length disagreement means the ordering
    broke upstream, and silently recycling values would attribute one consumer's
    prior to another consumer's coefficients.
    """
    arr = jnp.asarray(value, dtype=jnp.float32)
    n_flat = sum(n_cells)
    if arr.ndim == 0:
        return jnp.broadcast_to(arr, (n_flat,))
    arr = arr.reshape(-1)
    if arr.shape[0] == len(n_cells):
        return _flat_scale_from_entry_sigmas(arr, n_cells)
    if arr.shape[0] == n_flat:
        return arr
    raise ValueError(
        f"normal.bundled hyperparameter {name!r} has length {arr.shape[0]}, "
        f"which is neither the entry count ({len(n_cells)}) nor the cell count "
        f"({n_flat}); a partitioned hyperparameter must align with one of them "
        f"in entry order (or be a scalar)"
    )

