def index_latents_by_indicator(
    latent_parents: tuple[StructuredArray, ...],
) -> dict[str, StructuredArray]:
    """Map latent indicator id -> parent ``StructuredArray``."""
    out: dict[str, StructuredArray] = {}
    for sa in latent_parents:
        key = sa.indicator.indicator
        if key in out:
            raise ValueError(
                f"duplicate latent indicator {key!r}; each indicator may "
                "appear at most once among latent parents"
            )
        out[key] = sa
    return out

def _bindings_for(
    parents: tuple[NodeMeta, ...],
    *,
    needed_indicators: set[str],
    needed_sources: set[str],
) -> Mapping[str, tuple[str, ...]]:
    """Sort ``parents`` into the three observation roles."""
    latents: list[str] = []
    biases: list[str] = []
    precisions: list[str] = []

    for p in parents:
        # ``NodeMeta.indicator`` is desugar's resolved code, and its docstring names
        # observation attachment as one of its readers; it is ``None`` on <=v3 graphs,
        # which fall back to the older ``extra``-else-id chain. Reading only the
        # fallback missed a v4 node that declares ``indicator:`` -- the latent then
        # matched nothing and the site resolved zero latent parents.
        ind = p.indicator or p.extra.get("indicator", p.node_id)
        src = p.extra.get("source")
        if str(ind) in needed_indicators:
            latents.append(p.node_id)
            continue
        if p.node_id.startswith("bias_"):
            src = src or p.node_id[5:]
            if str(src) in needed_sources:
                biases.append(p.node_id)
            continue
        if p.node_id.startswith("precision_"):
            src = src or p.node_id[10:]
            if str(src) in needed_sources:
                precisions.append(p.node_id)
            continue
        if p.kind in ("source_bias", "bias"):
            if src is not None and str(src) in needed_sources:
                biases.append(p.node_id)
            continue
        if p.kind in ("source_precision", "precision"):
            if src is not None and str(src) in needed_sources:
                precisions.append(p.node_id)
            continue

    return {
        "latent": tuple(latents),
        "source_bias": tuple(biases),
        "source_precision": tuple(precisions),
    }

def _resolve_beta_observation_bindings(
    *,
    child: NodeMeta,
    parents: tuple[NodeMeta, ...],
    hyperparameters: Mapping[str, Any],
) -> Mapping[str, tuple[str, ...]]:
    return resolve_observation_bindings(
        child=child, parents=parents, hyperparameters=hyperparameters
    )

def _beta_from_logit(loc: Any, scale: Any) -> Any:
    """Beta with the mean the logit location implies and κ from the scale."""
    mu = 1.0 / (1.0 + jnp.exp(-loc))
    kappa = jnp.maximum(1.0 / jnp.square(scale), 1.0)
    return dist.Beta(
        jnp.maximum(mu * kappa, 1e-3), jnp.maximum((1.0 - mu) * kappa, 1e-3)
    )

def _collapse_to(
    latent: StructuredArray,
    keep: tuple[str, ...],
    weights: StructuredArray | None,
) -> StructuredArray:
    """The latent aggregated down to ``keep``, in the unit it already has.

    A grid that names fewer axes than its latent has is observing a coarser
    quantity, not a replicated one, so the latent is aggregated rather than
    refused. Which aggregation is not the author's to declare: exactly one choice
    preserves the unit, and it follows from the family. A ``count`` sums, so it
    needs no weights at all; a ``rate`` is a population-weighted mean, so it needs
    the weights for the axis being collapsed.

    Those weights are the grid's ``population`` parent -- the consumer holds them,
    because it is the consumer that asked for the collapse. ``None`` falls through
    to the latent's own pointer, which is what a latent that carries one wants;
    when there is neither, the reduction raises and names the indicator itself.
    """
    if latent.indicator.family == "count":
        return latent.cumulative(keep_disaggregated=keep)
    return latent.per_capita(keep_disaggregated=keep, weights=weights)

def _resolve_lognormal_observation_bindings(
    *,
    child: NodeMeta,
    parents: tuple[NodeMeta, ...],
    hyperparameters: Mapping[str, Any],
) -> Mapping[str, tuple[str, ...]]:
    return resolve_observation_bindings(
        child=child, parents=parents, hyperparameters=hyperparameters
    )

def _resolve_normal_observation_bindings(
    *,
    child: NodeMeta,
    parents: tuple[NodeMeta, ...],
    hyperparameters: Mapping[str, Any],
) -> Mapping[str, tuple[str, ...]]:
    return resolve_observation_bindings(
        child=child, parents=parents, hyperparameters=hyperparameters
    )

def _as_gap_floors(min_gap: MinGap, n_gaps: int) -> jnp.ndarray:
    """Broadcast a scalar or length-``n_gaps`` sequence to a 1-d floor vector."""
    if isinstance(min_gap, (int, float)):
        if float(min_gap) < 0.0:
            raise ValueError(f"min_gap must be >= 0, got {min_gap}")
        return jnp.full((n_gaps,), float(min_gap))

    # Concrete sequence (config / tests) — validate in Python before tracing.
    if isinstance(min_gap, (list, tuple)):
        vals = [float(x) for x in min_gap]
        if any(v < 0.0 for v in vals):
            raise ValueError(f"min_gap entries must be >= 0, got {vals}")
        if len(vals) == 1:
            vals = vals * n_gaps
        elif len(vals) != n_gaps:
            raise ValueError(f"min_gap length {len(vals)} != n_gaps={n_gaps}")
        return jnp.asarray(vals, dtype=jnp.float32)

    floors = jnp.asarray(min_gap, dtype=jnp.float32)
    if floors.ndim != 1:
        raise ValueError(f"min_gap must be scalar or 1-d, got shape {floors.shape}")
    if floors.shape[0] == 1:
        floors = jnp.broadcast_to(floors, (n_gaps,))
    elif int(floors.shape[0]) != n_gaps:
        # shape[0] is static for these configs
        raise ValueError(
            f"min_gap length {int(floors.shape[0])} != n_gaps={n_gaps}"
        )
    return floors

def scatter_params(specs: tuple[SiteSpec, ...]) -> dict[str, "jnp.ndarray"]:
    """Concatenate each parameter field across entries, per name, in order.

    Keyed by name throughout: fields with different names never mix, and order
    within a name is never permuted. Split out from ``bundle_sites`` so the
    round-trip property can be tested against ``gather_draw`` directly,
    without drawing anything.
    """
    flat: dict[str, "jnp.ndarray"] = {}
    for key in specs[0].params:
        flat[key] = jnp.concatenate(
            [spec.broadcast_params()[key].reshape((spec.n_cells,)) for spec in specs]
        )
    return flat

def gather_draw(
    value: "jnp.ndarray",
    specs: tuple[SiteSpec, ...],
    layout: tuple[tuple[int, int], ...],
) -> tuple[StructuredArray, ...]:
    """Slice one flat draw back into per-entry ``StructuredArray``s.

    Uses the same ``layout`` the scatter used, which is why an entry always
    reads back exactly the cells its own parameters went into.
    """
    flat = jnp.asarray(value).reshape((sum(size for _, size in layout),))
    return tuple(
        StructuredArray(
            array=flat[offset : offset + size].reshape(spec.cell_shape),
            axes=spec.axes,
            indicator=spec.indicator,
            population=spec.population,
        )
        for spec, (offset, size) in zip(specs, layout)
    )

def _resolve_standardize_bindings(
    *,
    child: NodeMeta,
    parents: tuple[NodeMeta, ...],
    hyperparameters: Mapping[str, Any],
) -> Mapping[str, tuple[str, ...]]:
    """Classify every parent into the single ``value`` role."""
    del child, hyperparameters
    return {"value": tuple(p.node_id for p in parents)}

def register() -> None:
    """Install this module's CPD entry in the global registry."""
    register_cpd(
        "standardize",
        "zscore",
        standardize_zscore,
        kind="deterministic",
        default_role="standardization",
        parameter_schema={
            "value": ParamDecl(
                description="The latent driver field in its natural unit; one.",
                min_count=1,
                max_count=1,
            ),
        },
        hyperparameter_schema={
            "center": HyperDecl(
                description="Mean of t(x) across the panel (standardization center).",
                default=0.0,
            ),
            "scale": HyperDecl(
                description="Sd of t(x) across the panel (standardization unit).",
                default=1.0,
            ),
            "transform": HyperDecl(
                description='Pre-centering transform: "identity" or "log".',
                default="identity",
            ),
        },
        resolve_bindings=_resolve_standardize_bindings,
    )

def step(carry: Any, target_t: Any) -> tuple[Any, Any]:
    p_t = (1.0 - kappa) * carry + kappa * target_t
    return p_t, p_t

def _segment_levels(raw: Any, n_segments: int, label: str) -> tuple[str, ...]:
    """The K output segment labels, defaulted or checked against K.

    Mirrors ``continuation_ratio.segment``: the author declares the K-1
    *transitions* (truthful for continuation-ratio, where a coefficient is a
    per-boundary "do you advance?") while ``segment_levels`` names the K outputs.
    """
    if raw is None:
        return tuple(f"S{i + 1}" for i in range(n_segments))
    levels = tuple(raw)
    if len(levels) != n_segments:
        raise ValueError(
            f"{label}: segment_levels has {len(levels)} labels but the transform "
            f"produces {n_segments} segments (transition axis length "
            f"{n_segments - 1} + 1)."
        )
    return levels

def site(loc: Any) -> Any:
    def prepared(value: Any) -> Any:
        if value is None:
            return None
        return jnp.broadcast_to(jnp.asarray(value, dtype=loc.dtype), loc.shape)

    distribution = truncated_normal(
        loc=loc,
        scale=scale_arr,
        low=prepared(low_bound),
        high=prepared(high_bound),
    )
    if demo_ndim:
        distribution = distribution.to_event(demo_ndim)
    return distribution

def prepared(value: Any) -> Any:
    if value is None:
        return None
    return jnp.broadcast_to(jnp.asarray(value, dtype=loc.dtype), loc.shape)

def _disaggregation_axes(
    declared: Any,
    weights_sa: StructuredArray,
    biases_sa: StructuredArray,
    driver_sas: tuple[StructuredArray, ...],
    structural_axes: tuple[str, ...],
    node: str,
) -> tuple[AxisMeta, ...]:
    """The disaggregation axes B, as ordered ``AxisMeta``.

    Unset -> inferred from the weights (their axes beyond the structural roles,
    in weights order). Declared -> the named set, each resolved to an ``AxisMeta``
    from whichever parent carries it; a name no parent carries is an error.
    """
    if declared is None:
        return tuple(
            a for a in weights_sa.axes
            if a.name not in structural_axes
        )
    pools = (weights_sa, biases_sa, *driver_sas)
    metas: list[AxisMeta] = []
    for nm in declared:
        meta = next(
            (sa.axes[sa.axis_names.index(nm)] for sa in pools if nm in sa.axis_names),
            None,
        )
        if meta is None:
            raise ValueError(
                f"transition_logits ({node!r}): disaggregation_axes lists "
                f"{nm!r}, but no parent carries it (cannot source its levels)."
            )
        metas.append(meta)
    return tuple(metas)

def _check_axis_levels(
    sa: StructuredArray, meta: AxisMeta, node: str, role: str
) -> None:
    """A parent carrying a B axis must match B's levels for it exactly."""
    if meta.name in sa.axis_names:
        found = sa.axes[sa.axis_names.index(meta.name)].levels
        if found != meta.levels:
            raise ValueError(
                f"transition_logits ({node!r}): {role} axis {meta.name!r} levels "
                f"{list(found)} do not match {list(meta.levels)}."
            )

def _driver_id(
    sa: StructuredArray, node: str, columns: tuple[str, ...] = ()
) -> str:
    """The node id of a driver parent -- the key its weight column is named for.

    ``columns`` is the declared driver axis, passed only so the ``_z`` bridge can
    fall back to the un-suffixed id when a standardizer's own id names no column
    (see ``_bridge_driver_keys``). Omit it and this is just the node id.
    """
    node_id = sa.node_id_or_raise(
        context=f"transition_logits ({node!r}): driver parent"
    )
    for candidate in driver_match_candidates(node_id):
        if candidate in columns:
            return candidate
    return node_id

def _cell_axes(sa: StructuredArray, disagg_names: tuple[str, ...]) -> tuple[AxisMeta, ...]:
    """A driver's axes minus the disaggregation axes -- its true cell grid."""
    return tuple(a for a in sa.axes if a.name not in disagg_names)

def _broadcast_grid(
    sa: StructuredArray, want_names: tuple[str, ...], want_shape: tuple[int, ...]
) -> "jnp.ndarray":
    """``sa.array`` reordered/broadcast to exactly ``want_names`` (-> ``want_shape``).

    Axes ``sa`` carries are moved into their ``want_names`` slot; axes it lacks
    are inserted as size-1 and broadcast to the target size. Callers guarantee
    ``sa`` carries no axis outside ``want_names``.
    """
    arr = sa.array
    names = list(sa.axis_names)
    for i, nm in enumerate(want_names):
        if nm in names:
            pos = names.index(nm)
            arr = jnp.moveaxis(arr, pos, i)
            names.pop(pos)
            names.insert(i, nm)
        else:
            arr = jnp.expand_dims(arr, i)
            names.insert(i, nm)
    return jnp.broadcast_to(arr, want_shape)

def _axis_pos(sa: StructuredArray, axis: str, node: str, role: str) -> int:
    """Index of ``axis`` in ``sa``, or a clear error naming what's available."""
    try:
        return sa.axis_names.index(axis)
    except ValueError:
        raise ValueError(
            f"transition_logits ({node!r}): {role} parent has no axis "
            f"{axis!r}; axes are {list(sa.axis_names)}."
        ) from None

def tex_value(value: Any) -> str:
    if isinstance(value, Mapping) and "from_data" in value:
        return r"\operatorname{data}(" + tex_text(value["from_data"]) + ")"
    if isinstance(value, (int, float)) and not isinstance(value, bool):
        if math.isinf(value):
            return ("-" if value < 0 else "") + r"\infty"
        return str(value)
    # Long arrays remain in the details rather than overflowing graph cards.
    if isinstance(value, list):
        if len(value) <= 5 and all(isinstance(x, (int, float)) for x in value):
            return r"\left[" + ",".join(tex_value(x) for x in value) + r"\right]"
        return tex_text("array (see details)")
    return tex_text(value)

def auto_flag(scope: Mapping[str, Any], name: str, inherited: bool) -> bool:
    for key in (name, "autoconstruct"):
        if scope.get(key) is not None:
            return bool(scope[key])
    return inherited

def family_equation(variable: str, cpd: Mapping[str, Any]) -> str:
    """Use NumPyro's scale-as-standard-deviation convention."""
    family = cpd.get("family")
    if family in {"normal", "lognormal"}:
        lhs = r"\log " + variable if family == "lognormal" else variable
        return lhs + r"\sim\mathcal{N}(\mu,\sigma^2)"
    if family == "beta":
        return variable + r"\sim\operatorname{Beta}(\alpha,\beta)"
    if family == "bernoulli":
        return variable + r"\sim\operatorname{Bernoulli}(p)"
    return (
        variable
        + r"\sim p_{"
        + tex_text(family or "unspecified")
        + r"}(\cdot\mid\mathrm{pa})"
    )

def node_equations(node: Mapping[str, Any]) -> list[str]:
    """Schematic equations verified against the named CPD implementations."""
    cpd = node.get("cpd") or {}
    hp = cpd.get("hyperparameters") or {}
    pair = (cpd.get("family"), cpd.get("constructor"))
    variable = symbol(node["id"])
    if pair == ("temporal", "segment_ordered_v0"):
        return [
            r"z_t=\boldsymbol v_t^{\mathsf T}\boldsymbol\beta,\quad F_{j,t}=\sigma(\tau_j-z_t)",
            r"\tau_1=\delta_1,\quad\tau_j=\tau_{j-1}+\operatorname{softplus}(\delta_j)+g_j\quad(2\leq j\leq K-1)",
            r"\boldsymbol\pi_t^*=(F_{1,t},\;F_{2,t}-F_{1,t},\;\ldots,\;1-F_{K-1,t})",
            r"\boldsymbol\pi_0=\boldsymbol\pi_0^*",
            r"\boldsymbol\pi_t=(1-\kappa)\boldsymbol\pi_{t-1}+\kappa\boldsymbol\pi_t^*\quad(t\geq1)",
        ]
    if pair == ("temporal", "segment_v0"):
        return [
            r"\eta_{j,t}=\boldsymbol v_t^{\mathsf T}\boldsymbol\beta_j,\quad r_{j,t}=\sigma(\eta_{j,t})\quad(1\leq j<K)",
            r"\pi^*_{k,t}=\left(\prod_{j<k}r_{j,t}\right)(1-r_{k,t})\quad(1\leq k<K)",
            r"\pi^*_{K,t}=\prod_{j=1}^{K-1}r_{j,t},\quad\boldsymbol\pi_0=\boldsymbol\pi_0^*",
            r"\boldsymbol\pi_t=(1-\kappa)\boldsymbol\pi_{t-1}+\kappa\boldsymbol\pi_t^*\quad(t\geq1)",
        ]
    if pair == ("temporal", "truncated_v0"):
        return [
            r"\mu_t=\boldsymbol v_t^{\mathsf T}\boldsymbol\beta,\quad m_0=\mu_0",
            r"m_t=(1-\kappa)x_{t-1}+\kappa\mu_t\quad(t\geq1)",
            r"x_t\sim\operatorname{TN}_{[L,U]}(m_t,s^2)",
        ]
    if pair == ("bernoulli", "constraint_v0"):
        difference = (
            r"\log\ell-\log u"
            if hp.get("transform", "absolute") == "log"
            else r"\ell-u"
        )
        return [
            r"\Pr(C=0)=\sigma\!\left(-\lambda(" + difference + r")\right)",
            r"C=0\quad\text{(synthetic evidence)}",
        ]
    return [family_equation(variable, cpd)]

def parent_refs(node: Mapping[str, Any]) -> list[dict[str, Any]]:
    refs = []
    for parent in node.get("parents") or []:
        if isinstance(parent, str):
            refs.append({"id": parent})
        elif isinstance(parent, Mapping) and "id" in parent:
            refs.append(dict(parent))
        else:
            raise ValueError(f"Invalid parent reference on {node['id']!r}: {parent!r}")
    return refs

def authored_value(value: Any) -> str:
    """Readable values, including unresolved data references, for the glossary."""
    return json.dumps(json_ready(value), ensure_ascii=False, default=str)

def distribution_semantics(
    variable: str, cpd: Mapping[str, Any], context: str, *, root_prior: bool = False
) -> tuple[str, list[dict]]:
    """Family notation is schematic unless a known root constructor supplies defaults."""
    family = cpd.get("family")
    hp = cpd.get("hyperparameters") or {}
    bindings = cpd.get("parameter_bindings") or {}
    symbols = []

    def define(tex: str, meaning: str) -> None:
        symbols.append({"tex": tex, "meaning": meaning})

    def parameter(tex: str, name: str, meaning: str) -> None:
        if name in bindings:
            value = f"parameter_bindings.{name} = {authored_value(bindings[name])}"
        elif name in hp:
            value = f"hyperparameters.{name} = {authored_value(hp[name])}"
        elif root_prior and name in {"loc", "scale"}:
            value = f"prior_v0 default {name} = {0.0 if name == 'loc' else 1.0}"
        else:
            value = f"{name} is not authored here"
        define(tex, f"{meaning}; {value}.")

    define(variable, "value governed by this distribution.")
    define(r"\sim", "is distributed according to the displayed family.")
    if family in {"normal", "lognormal"}:
        parameter(
            r"\mu",
            "loc",
            "location on the log scale" if family == "lognormal" else "location",
        )
        parameter(
            r"\sigma",
            "scale",
            "positive standard deviation on the log scale"
            if family == "lognormal"
            else "positive standard deviation",
        )
        define(
            r"\mathcal N",
            "Normal distribution; the second displayed argument is variance, sigma squared.",
        )
        if family == "lognormal":
            define(
                r"\log",
                "natural logarithm; the value is positive and its logarithm is Normal.",
            )
    elif family == "beta":
        shape_names = (
            ("a", "b") if cpd.get("constructor") == "prior_v0" else ("alpha", "beta")
        )
        parameter(
            r"\alpha",
            shape_names[0],
            "first positive Beta shape",
        )
        parameter(
            r"\beta",
            shape_names[1],
            "second positive Beta shape",
        )
        define(
            r"\operatorname{Beta}",
            "Beta distribution on (0, 1).",
        )
    elif family == "bernoulli":
        parameter(
            "p",
            "probs",
            "probability of value 1; logits require a sigmoid conversion.",
        )
        define(
            r"\operatorname{Bernoulli}",
            "binary distribution with probability p of 1 and 1-p of 0.",
        )
    else:
        define(
            "p_{" + tex_text(family or "unspecified") + "}",
            "generic family law.",
        )
        define(
            r"\cdot", "placeholder for the value at which the family law is evaluated."
        )
        define(
            r"\mathrm{pa}",
            "parent inputs and parameters; roles follow authored parameter bindings.",
        )
    if any(
        isinstance(value, Mapping) and "from_data" in value for value in hp.values()
    ):
        define(
            r"\operatorname{data}",
            "a configured data-derived quantity; the argument names its reference.",
        )
    explanation = (
        f"Known {family}.prior_v0 root distribution; omitted loc and scale default to 0 and 1."
        if root_prior
        else f"{(family or 'unspecified').capitalize()} distribution, shown in family notation."
    )
    return explanation, symbols

def parameter(tex: str, name: str, meaning: str) -> None:
    if name in bindings:
        value = f"parameter_bindings.{name} = {authored_value(bindings[name])}"
    elif name in hp:
        value = f"hyperparameters.{name} = {authored_value(hp[name])}"
    elif root_prior and name in {"loc", "scale"}:
        value = f"prior_v0 default {name} = {0.0 if name == 'loc' else 1.0}"
    else:
        value = f"{name} is not authored here"
    define(tex, f"{meaning}; {value}.")

def model_semantics(
    node: Mapping[str, Any],
    definitions: Mapping[str, Mapping[str, Any]],
    incoming: list[str],
) -> tuple[str, list[dict], list[str]]:
    """Local glossary tied to authored bindings, without running the desugarer."""
    name = node["id"]
    cpd = node.get("cpd") or {}
    hp = cpd.get("hyperparameters") or {}
    bindings = cpd.get("parameter_bindings") or {}
    pair = (cpd.get("family"), cpd.get("constructor"))
    temporal = pair[0] == "temporal" and pair[1] in {
        "truncated_v0",
        "segment_v0",
        "segment_ordered_v0",
    }
    constraint = pair == ("bernoulli", "constraint_v0")
    symbols: list[dict] = []
    extra_equations: list[str] = []

    def define(tex: str, meaning: str) -> None:
        symbols.append({"tex": tex, "meaning": meaning})

    def setting(tex: str, key: str, default: Any, meaning: str) -> None:
        define(
            tex,
            f"{meaning}; {key} = {authored_value(hp.get(key, default))}"
            + (" (constructor default)." if key not in hp else " (authored)."),
        )

    def bound(role: str, tag: str) -> list[str]:
        if role in bindings:
            value = bindings[role]
            return [value] if isinstance(value, str) else list(value)
        return [
            p
            for p in incoming
            if (definitions.get(p, {}).get("extra") or {}).get(tag) == role
        ]

    def role_description(role: str, tag: str) -> str:
        parents = bound(role, tag)
        if parents:
            origin = "parameter_bindings" if role in bindings else f"parent extra.{tag}"
            return f"{role} from {origin}: {', '.join(parents)}"
        override = (cpd.get("priors") or {}).get(role)
        if override is not None:
            return f"authored cpd.priors.{role} override"
        return f"{role} from the default prior"

    if not temporal and not constraint:
        explanation, symbols = distribution_semantics(
            symbol(name),
            cpd,
            name,
            root_prior=pair[1] == "prior_v0" and pair[0] in {"normal", "lognormal"},
        )
        if incoming:
            define(
                r"\mathrm{pa}",
                "authored parent nodes: " + ", ".join(incoming) + ".",
            )
    elif temporal:
        ordered = pair[1] == "segment_ordered_v0"
        segmented = pair[1] != "truncated_v0"
        coeffs = role_description("mean_coeffs", "truncated_role")
        predictors = (
            bound("predictors", "truncated_role")
            if "predictors" in bindings
            else [
                p for p in incoming if p not in bound("mean_coeffs", "truncated_role")
            ]
        )
        define(
            "t",
            f"zero-based index on year_axis = {authored_value(hp.get('year_axis', 'year'))}; aligned cell axes are implicit.",
        )
        setting(
            r"\kappa",
            "kappa",
            0.5,
            "fraction of the target gap closed each step, in [0, 1]",
        )
        define(
            r"\boldsymbol v_t",
            "predictor vector: "
            + (
                "parameter_bindings.predictors"
                if "predictors" in bindings
                else "authored predictor parents"
            )
            + " = "
            + authored_value(predictors)
            + f". Channels match {authored_value(hp.get('coefficient_axis', 'coefficient'))} levels; normalized parents use synthesized ids and segment parents expand by segment. "
            + (
                "No intercept: its bias coefficient is zeroed."
                if ordered
                else f"The bias_level = {authored_value(hp.get('bias_level', 'bias'))} channel, when present, is constant 1 and its coefficient is the intercept."
            ),
        )
        define(
            r"{}^{\mathsf T}",
            "transpose; the product sums matched coefficient and predictor channels across aligned cell axes.",
        )
        if ordered:
            mode = hp.get("slope_mode", "ref")
            slope = (
                f"reference transition column at zero-based slope_ref_index = {hp.get('slope_ref_index', 0)}; other slope cells are unused"
                if mode == "ref"
                else "arithmetic mean across transition columns"
            )
            define(
                r"\boldsymbol\beta",
                f"shared non-bias slopes from {coeffs}; slope_mode = {authored_value(mode)} uses the {slope}.",
            )
            define(
                "z_t",
                "intercept-free ordered score; larger values shift mass toward higher segments.",
            )
            define(
                r"\delta_j",
                f"raw threshold delta from {coeffs}, bias_level = {authored_value(hp.get('bias_level', 'bias'))}, transition j-1; delta_1 is a threshold location, not an intercept.",
            )
            define(
                r"\tau_j",
                "ordered cut point: tau_1 equals delta_1; later points add a positive softplus gap and nonnegative floor.",
            )
            define(
                r"\operatorname{softplus}",
                "function a ↦ log(1 + exp(a)); guarantees a positive gap before adding its floor.",
            )
            if hp.get("min_gaps") is not None:
                define(
                    "g_j",
                    f"nonnegative threshold-gap floor for j=2,…,K-1; min_gaps = {authored_value(hp['min_gaps'])} overrides min_gap at index j-2.",
                )
            else:
                setting(
                    "g_j",
                    "min_gap",
                    0.0,
                    "same nonnegative floor for every threshold gap j=2,…,K-1",
                )
            define(
                "F_{j,t}",
                "cumulative target probability through segment j; differences produce interior shares.",
            )
        else:
            define(
                r"\boldsymbol\beta_j" if segmented else r"\boldsymbol\beta",
                f"coefficients from {coeffs}; "
                + (
                    "one coefficient vector per transition j, including its own bias intercept."
                    if segmented
                    else "bias intercept and predictor slopes; the linear target has no sigmoid or clipping."
                ),
            )
        if segmented:
            levels = hp.get("segment_levels")
            define(
                "K",
                (
                    f"{len(levels)} segments: {authored_value(levels)}. "
                    if isinstance(levels, list) and levels
                    else f"number of segments: {authored_value(hp.get('transition_axis', 'transition'))} length plus one. "
                )
                + f"Output axis: {authored_value(hp.get('segment_axis', 'segment'))}.",
            )
            define("j", "one-based boundary/transition index, 1,…,K-1.")
            define(
                r"\sigma",
                "logistic sigmoid, a ↦ 1/(1 + exp(-a)); not a noise standard deviation.",
            )
            define(
                r"\boldsymbol\pi_t^*",
                "instantaneous K-vector of nonnegative target shares summing to 1; * means target, not multiplication.",
            )
            define(
                r"\boldsymbol\pi_t",
                "output shares: equal the target at t=0, then adjust deterministically in share space, not score/logit space.",
            )
            if not ordered:
                define("k", "one-based segment index, 1,…,K.")
                define(
                    r"\eta_{j,t}",
                    "linear logit for sequential gate j, with its own intercept and slopes; not an ordered cut point.",
                )
                define(
                    "r_{j,t}",
                    "conditional probability of advancing through gate j given arrival at that gate.",
                )
                define(
                    r"\pi^*_{k,t}",
                    "component k of the target share vector; fail gate k after passing all earlier gates, or pass every gate for segment K.",
                )
                define(
                    r"\prod",
                    "product over earlier gates, with the empty product equal to 1 for the first segment.",
                )
            explanation = f"Predictors map to {'ordered-logit interval probabilities with shared slopes' if ordered else 'continuation-ratio probabilities with separate gates'}, then shares partially adjust. No sampling noise is added."
        else:
            define(
                "x_t",
                "state/output at time t, not the predictor vector; x at t-1 is the previous sampled state.",
            )
            define(
                r"\mu_t",
                "unclipped linear target on the outcome scale, not necessarily inside the truncation bounds.",
            )
            define(
                "m_t",
                "pre-truncation Normal location: target at t=0, then previous state blended with current target; not the truncated expectation.",
            )
            setting("L", "low", 0.0, "lower support bound")
            setting("U", "high", 1.0, "upper support bound")
            setting(
                "s",
                "scale",
                0.05,
                "positive Normal standard deviation before truncation",
            )
            define(
                r"\operatorname{TN}_{[L,U]}",
                "Normal restricted to [L,U]; arguments are pre-truncation location and variance s squared.",
            )
            define(
                r"\sim",
                "sampled conditionally on current predictors, coefficients, and previous state.",
            )
            explanation = "Draws a bounded state around a partially adjusted linear target. Truncation, rather than target clipping, enforces support."
    else:
        define(
            "C",
            "synthetic binary constraint; conditioning on 0 softly favors lower ≤ upper, not a hard inequality.",
        )
        define(r"\Pr", "probability under the constraint Bernoulli distribution.")
        define(r"\sigma", "logistic sigmoid, a ↦ 1/(1 + exp(-a)).")
        setting(
            r"\lambda", "tightness", 50.0, "multiplier controlling penalty steepness"
        )
        for role, tex in (("lower", r"\ell"), ("upper", "u")):
            spec = hp.get(role + "_spec")
            selection = "whole operand (no selection)"
            if spec is not None:
                selection = (
                    f"select levels {authored_value(spec.get('levels'))} on axis {authored_value(spec.get('axis'))}; "
                    + (
                        "raw sum of selected levels, dropping the axis (no population weighting)"
                        if spec.get("sum", True)
                        else "retain the selected axis without summing"
                    )
                )
            define(
                tex,
                f"{role_description(role, 'constraint_role')}; {role}_spec {selection}.",
            )
        if hp.get("transform", "absolute") == "log":
            define(
                r"\log",
                "natural log of positive aggregated operands; transform = log compares their log ratio.",
            )
        explanation = f"Compares selected operands using transform = {hp.get('transform', 'absolute')}. Evidence C=0 penalizes violations; equality has probability 1/2."

    # Inline normalizers are authored shorthand for data-referenced zscore nodes.
    for ref in parent_refs(node):
        if ref.get("normalize") is None:
            continue
        parent = ref["id"]
        parent_def = definitions.get(parent, {})
        norm = ref["normalize"] if isinstance(ref["normalize"], Mapping) else {}
        transform = norm.get("transform") or (parent_def.get("extra") or {}).get(
            "transform", "identity"
        )
        normalized = norm.get("id") or parent + "_z"
        raw, channel = symbol(parent), symbol(normalized, "v")
        center, scale = symbol(normalized, "a"), symbol(normalized, "b")
        transformed = r"\log " + raw if transform == "log" else raw
        if transform not in {"log", "identity"}:
            transformed = tex_text(transform) + "(" + raw + ")"
            define(
                tex_text(transform),
                "authored normalization transform.",
            )
        extra_equations.append(
            channel + r"=\frac{" + transformed + "-" + center + "}{" + scale + "}"
        )
        define(raw, "raw value before normalization.")
        define(
            channel,
            f"normalized channel; synthesized id {normalized} is used for coefficient matching; transform = {transform} precedes centering and scaling.",
        )
        indicator = (parent_def.get("extra") or {}).get("data_indicator")
        if indicator is None:
            parent_hp = (parent_def.get("cpd") or {}).get("hyperparameters") or {}
            for key in ("loc", "center"):
                value = parent_hp.get(key)
                if (
                    isinstance(value, Mapping)
                    and value.get("from_data") == "standardize.center"
                ):
                    indicator = (value.get("args") or {}).get("indicator", parent)
                    break
        indicator = (
            norm.get("indicator") or indicator or parent_def.get("indicator") or parent
        )
        for tex, field in ((center, "center"), (scale, "scale")):
            statistic = (
                "centering mean"
                if field == "center"
                else "nonzero scaling standard deviation"
            )
            define(
                tex,
                f"{statistic} on the transformed scale, from standardize.{field} for indicator {indicator}; data-derived, not estimated here.",
            )
        if transform == "log":
            define(
                r"\log",
                "natural logarithm of a positive value; standardization is on the log scale.",
            )
    # One local entry per symbol (e.g. multiple log-normalized parents).
    merged: dict[str, str] = {}
    for item in symbols:
        tex, meaning = item["tex"], item["meaning"]
        if tex not in merged:
            merged[tex] = meaning
        elif meaning not in merged[tex]:
            merged[tex] += " " + meaning
    return (
        explanation,
        [{"tex": tex, "meaning": meaning} for tex, meaning in merged.items()],
        extra_equations,
    )

def setting(tex: str, key: str, default: Any, meaning: str) -> None:
    define(
        tex,
        f"{meaning}; {key} = {authored_value(hp.get(key, default))}"
        + (" (constructor default)." if key not in hp else " (authored)."),
    )

def bound(role: str, tag: str) -> list[str]:
    if role in bindings:
        value = bindings[role]
        return [value] if isinstance(value, str) else list(value)
    return [
        p
        for p in incoming
        if (definitions.get(p, {}).get("extra") or {}).get(tag) == role
    ]

def role_description(role: str, tag: str) -> str:
    parents = bound(role, tag)
    if parents:
        origin = "parameter_bindings" if role in bindings else f"parent extra.{tag}"
        return f"{role} from {origin}: {', '.join(parents)}"
    override = (cpd.get("priors") or {}).get(role)
    if override is not None:
        return f"authored cpd.priors.{role} override"
    return f"{role} from the default prior"

def dependency_label(parent: str, ref: Mapping[str, Any], roles: list[str]) -> str:
    variable = symbol(parent)
    norm = ref.get("normalize")
    if norm is not None:
        transform = (
            norm.get("transform", "identity")
            if isinstance(norm, Mapping)
            else "identity"
        )
        if transform == "log":
            variable = r"\operatorname{std}(\log " + variable + ")"
        elif transform == "identity":
            variable = r"\operatorname{std}(" + variable + ")"
        else:
            variable = (
                r"\operatorname{std}(" + tex_text(transform) + "(" + variable + "))"
            )
    return tex_text(", ".join(roles)) + r"\colon " + variable if roles else variable

def prior_fragments(role: str, value: Mapping[str, Any]):
    """A prior role may hold one override or a keyed fan-out of overrides."""
    fields = {"id", "include_axes", "bundle_id", "cpd"}
    if not value or fields.intersection(value):
        yield role, value
    else:
        for key, override in value.items():
            if not isinstance(override, Mapping):
                raise ValueError(f"Invalid prior override at {role}.{key}")
            yield from prior_fragments(f"{role}.{key}", override)

def build_diagram(
    config: Mapping[str, Any], *, priors: bool = True, observations: bool = True
) -> Diagram:
    if not isinstance(config, Mapping) or config.get("version") != 4:
        raise ValueError("Expected a YAML mapping with version: 4")
    authored = config.get("nodes")
    if not isinstance(authored, list) or not authored:
        raise ValueError("The config must contain a non-empty nodes list")
    nodes: dict[str, Node] = {}
    definitions: dict[str, Mapping[str, Any]] = {}
    edges: list[Edge] = []
    policy = dict(config.get("observation_defaults") or {})
    root_priors = auto_flag(config, "autoconstruct_priors", True)
    root_obs = auto_flag(config, "autoconstruct_obs", True)

    for definition in authored:
        if not isinstance(definition, Mapping) or not isinstance(
            definition.get("id"), str
        ):
            raise ValueError("Every node needs a string id")
        node_id = definition["id"]
        if node_id in definitions:
            raise ValueError(f"Duplicate node id: {node_id}")
        definitions[node_id] = definition
        cpd = definition.get("cpd") or {}
        constructor = cpd.get("constructor", "unspecified")
        kind = "constraint" if constructor == "constraint_v0" else "model"
        note = f"{cpd.get('family', 'unspecified')} / {constructor}"
        if definition.get("indicator"):
            note += f" · indicator: {definition['indicator']}"
        nodes["model:" + node_id] = Node(
            "model:" + node_id,
            node_id,
            kind,
            node_equations(definition),
            note,
            dict(definition),
        )

    def connect(parent: str, child: str, label: str) -> None:
        if parent not in definitions or child not in definitions:
            raise ValueError(f"Unknown node in dependency: {parent!r} -> {child!r}")
        edge = Edge("model:" + parent, "model:" + child, label)
        # Parameter bindings and authored edges can name the same connection.
        if not any(e.parent == edge.parent and e.child == edge.child for e in edges):
            edges.append(edge)

    def add_prior(
        consumer: str, node_id: str, role: str, override: Mapping[str, Any]
    ) -> None:
        key = f"prior:{node_id}:{role}"
        prior_cpd = override.get("cpd") or {}
        variable = symbol(node_id + ":" + role, r"\theta")
        if prior_cpd.get("family"):
            equations = [family_equation(variable, prior_cpd)]
            note = "Authored prior override; omitted fields use framework defaults"
            explanation, symbols = distribution_semantics(
                variable, prior_cpd, f"{node_id} prior role {role}"
            )
        else:
            equations = [variable + r"\sim p_{\mathrm{default}}(\cdot)"]
            note = "Partial/default prior; distribution structure not resolved"
            explanation = "Partial prior: authored fields are shown; the framework supplies its remaining structure and defaults."
            symbols = [
                {
                    "tex": variable,
                    "meaning": f"parameter governed by prior role {role}; authored id = {override.get('id') or '(not supplied)'}.",
                },
                {
                    "tex": r"p_{\mathrm{default}}",
                    "meaning": "framework default prior law, not an assumed Normal distribution.",
                },
                {
                    "tex": r"\cdot",
                    "meaning": "placeholder for the parameter value in that law.",
                },
                {
                    "tex": r"\sim",
                    "meaning": "is distributed according to that prior law.",
                },
            ]
            hp = prior_cpd.get("hyperparameters") or {}
            supplied = [
                tex_text(name) + "=" + tex_value(hp[name])
                for name in ("loc", "scale")
                if name in hp
            ]
            if supplied:
                equations.append(r",\quad ".join(supplied))
                for parameter in ("loc", "scale"):
                    if parameter in hp:
                        symbols.append(
                            {
                                "tex": tex_text(parameter),
                                "meaning": f"authored hyperparameters.{parameter} = {authored_value(hp[parameter])} for prior role {role}.",
                            }
                        )
                if any(
                    isinstance(hp.get(p), Mapping) and "from_data" in hp[p]
                    for p in ("loc", "scale")
                ):
                    symbols.append(
                        {
                            "tex": r"\operatorname{data}",
                            "meaning": f"data reference for prior role {role}; no data is loaded.",
                        }
                    )
        nodes[key] = Node(
            key,
            override.get("id") or f"{node_id} · {role}",
            "prior",
            equations,
            note,
            dict(override),
            explanation,
            symbols,
        )
        edges.append(Edge(key, consumer, tex_text(role.rsplit(".", 1)[-1]), "prior"))
        for nested_role, nested in (prior_cpd.get("priors") or {}).items():
            if nested is not None:
                for fragment_role, fragment in prior_fragments(nested_role, nested):
                    add_prior(key, node_id, f"{role}.{fragment_role}", fragment)

    for node_id, definition in definitions.items():
        cpd = definition.get("cpd") or {}
        bindings = cpd.get("parameter_bindings") or {}
        refs = {r["id"]: r for r in parent_refs(definition)}
        for role, bound in bindings.items():
            for parent in [bound] if isinstance(bound, str) else bound:
                refs.setdefault(parent, {"id": parent})
        for parent, ref in refs.items():
            roles = [
                role
                for role, bound in bindings.items()
                if parent in ([bound] if isinstance(bound, str) else bound)
            ]
            if ref.get("normalize") is not None:
                norm = (
                    dict(ref["normalize"])
                    if isinstance(ref["normalize"], Mapping)
                    else {}
                )
                if not norm.get("transform"):
                    norm["transform"] = (
                        definitions.get(parent, {}).get("extra") or {}
                    ).get("transform", "identity")
                ref = {**ref, "normalize": norm}
            connect(parent, node_id, dependency_label(parent, ref, roles))

        if priors:
            declared_priors = dict(cpd.get("priors") or {})
            # Known temporal constructors declare mean_coeffs as an automatic
            # parameter role. Do not resolve its effect-group/default structure.
            if cpd.get("family") == "temporal" and cpd.get("constructor") in {
                "truncated_v0",
                "segment_v0",
                "segment_ordered_v0",
            }:
                enabled = auto_flag(definition, "autoconstruct_priors", root_priors)
                enabled = auto_flag(cpd, "autoconstruct_priors", enabled)
                if enabled and not bindings.get("mean_coeffs"):
                    declared_priors.setdefault("mean_coeffs", {})
            for role, override in declared_priors.items():
                if override is None:
                    continue
                for fragment_role, fragment in prior_fragments(role, override):
                    add_prior("model:" + node_id, node_id, fragment_role, fragment)

        if observations:
            entries = definition.get("obs") or []
            if isinstance(entries, Mapping):
                entries = [entries]
            for index, entry in enumerate(entries):
                key = f"obs:{node_id}:{index}"
                obs_cpd = entry.get("cpd") or {}
                concrete = (
                    entry.get("source") is not None and entry.get("unit") is not None
                )
                note = (
                    "Authored observation specification"
                    if concrete
                    else "Authored observation template; data-dependent"
                )
                explanation, symbols = distribution_semantics(
                    symbol(node_id, "y"),
                    obs_cpd,
                    f"{entry.get('id') or 'observation ' + str(index + 1)} of {node_id}",
                )
                metadata = ", ".join(
                    f"{field} = {authored_value(entry[field])}"
                    for field in ("source", "unit")
                    if entry.get(field) is not None
                )
                if metadata:
                    explanation += f" Measurement of {node_id}; {metadata}."
                symbols[0]["meaning"] = (
                    f"measured response for {node_id}, not the latent state."
                )
                nodes[key] = Node(
                    key,
                    entry.get("id") or f"{node_id} · observation {index + 1}",
                    "observation",
                    [family_equation(symbol(node_id, "y"), obs_cpd)],
                    note,
                    dict(entry),
                    explanation,
                    symbols,
                )
                edges.append(
                    Edge("model:" + node_id, key, r"p(y\mid x,\psi)", "observation")
                )
            obs_enabled = auto_flag(definition, "autoconstruct_obs", root_obs)
            constructor = cpd.get("constructor", "")
            eligible = definition.get("role") in {
                "population",
                "segment",
                "indicator_latent",
            } or (
                cpd.get("family") == "temporal"
                and constructor in {"truncated_v0", "segment_v0", "segment_ordered_v0"}
            )
            if obs_enabled and eligible:
                key = f"obs-auto:{node_id}"
                indicator = definition.get("indicator", node_id)
                source = (policy.get("source_by_indicator") or {}).get(indicator)
                note = "Potential automatic observations; only instantiated if matching data exists"
                if source:
                    note += f" · source: {source}"
                nodes[key] = Node(
                    key,
                    f"{node_id} · data template",
                    "template",
                    [symbol(node_id, "y") + r"\sim p_{\mathrm{unit}}(y\mid x,\psi)"],
                    note,
                    {
                        "indicator": indicator,
                        "source": source,
                        "observation_defaults": policy,
                    },
                    f"Automatic measurement likelihood for {indicator}, instantiated only if matching data exists. Its family follows the observation unit.",
                    [
                        {
                            "tex": symbol(node_id, "y"),
                            "meaning": f"measured response for {indicator}"
                            + (f", source {source}." if source else "."),
                        },
                        {
                            "tex": "y",
                            "meaning": "the same response as on the left-hand side.",
                        },
                        {
                            "tex": "x",
                            "meaning": f"latent value of {node_id}, aggregated as required by the observation unit.",
                        },
                        {
                            "tex": r"\psi",
                            "meaning": "likelihood parameters, such as dispersion or source effects.",
                        },
                        {
                            "tex": r"p_{\mathrm{unit}}",
                            "meaning": "likelihood family selected by the observation unit.",
                        },
                        {
                            "tex": r"\sim",
                            "meaning": "is distributed according to this likelihood.",
                        },
                    ],
                )
                edges.append(
                    Edge("model:" + node_id, key, r"p(y\mid x,\psi)", "observation")
                )

    for edge in config.get("edges") or []:
        if isinstance(edge, Mapping):
            parent, child = edge["parent"], edge["child"]
        else:
            parent, child = edge
        connect(parent, child, symbol(parent))
    graph = nx.DiGraph()
    graph.add_nodes_from(nodes)
    graph.add_edges_from((e.parent, e.child) for e in edges)
    if not nx.is_directed_acyclic_graph(graph):
        raise ValueError("The authored network contains a directed cycle")
    for node_id, definition in definitions.items():
        model = nodes["model:" + node_id]
        incoming = [
            edge.parent.removeprefix("model:")
            for edge in edges
            if edge.child == model.key and edge.kind == "dependency"
        ]
        model.explanation, model.symbols, extra_equations = model_semantics(
            definition, definitions, incoming
        )
        model.equations.extend(extra_equations)
        model.normalization_equations = extra_equations
    return Diagram(nodes, edges, policy)

def connect(parent: str, child: str, label: str) -> None:
    if parent not in definitions or child not in definitions:
        raise ValueError(f"Unknown node in dependency: {parent!r} -> {child!r}")
    edge = Edge("model:" + parent, "model:" + child, label)
    # Parameter bindings and authored edges can name the same connection.
    if not any(e.parent == edge.parent and e.child == edge.child for e in edges):
        edges.append(edge)

def add_prior(
    consumer: str, node_id: str, role: str, override: Mapping[str, Any]
) -> None:
    key = f"prior:{node_id}:{role}"
    prior_cpd = override.get("cpd") or {}
    variable = symbol(node_id + ":" + role, r"\theta")
    if prior_cpd.get("family"):
        equations = [family_equation(variable, prior_cpd)]
        note = "Authored prior override; omitted fields use framework defaults"
        explanation, symbols = distribution_semantics(
            variable, prior_cpd, f"{node_id} prior role {role}"
        )
    else:
        equations = [variable + r"\sim p_{\mathrm{default}}(\cdot)"]
        note = "Partial/default prior; distribution structure not resolved"
        explanation = "Partial prior: authored fields are shown; the framework supplies its remaining structure and defaults."
        symbols = [
            {
                "tex": variable,
                "meaning": f"parameter governed by prior role {role}; authored id = {override.get('id') or '(not supplied)'}.",
            },
            {
                "tex": r"p_{\mathrm{default}}",
                "meaning": "framework default prior law, not an assumed Normal distribution.",
            },
            {
                "tex": r"\cdot",
                "meaning": "placeholder for the parameter value in that law.",
            },
            {
                "tex": r"\sim",
                "meaning": "is distributed according to that prior law.",
            },
        ]
        hp = prior_cpd.get("hyperparameters") or {}
        supplied = [
            tex_text(name) + "=" + tex_value(hp[name])
            for name in ("loc", "scale")
            if name in hp
        ]
        if supplied:
            equations.append(r",\quad ".join(supplied))
            for parameter in ("loc", "scale"):
                if parameter in hp:
                    symbols.append(
                        {
                            "tex": tex_text(parameter),
                            "meaning": f"authored hyperparameters.{parameter} = {authored_value(hp[parameter])} for prior role {role}.",
                        }
                    )
            if any(
                isinstance(hp.get(p), Mapping) and "from_data" in hp[p]
                for p in ("loc", "scale")
            ):
                symbols.append(
                    {
                        "tex": r"\operatorname{data}",
                        "meaning": f"data reference for prior role {role}; no data is loaded.",
                    }
                )
    nodes[key] = Node(
        key,
        override.get("id") or f"{node_id} · {role}",
        "prior",
        equations,
        note,
        dict(override),
        explanation,
        symbols,
    )
    edges.append(Edge(key, consumer, tex_text(role.rsplit(".", 1)[-1]), "prior"))
    for nested_role, nested in (prior_cpd.get("priors") or {}).items():
        if nested is not None:
            for fragment_role, fragment in prior_fragments(nested_role, nested):
                add_prior(key, node_id, f"{role}.{fragment_role}", fragment)

def json_ready(value: Any) -> Any:
    """Preserve non-finite YAML bounds as text in the browser's strict JSON."""
    if isinstance(value, float) and not math.isfinite(value):
        return str(value)
    if isinstance(value, Mapping):
        return {str(key): json_ready(item) for key, item in value.items()}
    if isinstance(value, (list, tuple)):
        return [json_ready(item) for item in value]
    return value

def inline_javascript(source: str) -> str:
    """Prevent script-like text inside JavaScript from closing its HTML element."""
    return re.sub(
        r"</script",
        lambda match: match[0].replace("</", r"<\/", 1),
        source,
        flags=re.IGNORECASE,
    )

def render_html(diagram: Diagram, title: str) -> str:
    """Bundle the local viewer assets and a script-safe graph into one HTML file."""
    keys = {key: f"n{i}" for i, key in enumerate(diagram.nodes)}
    payload = {
        "title": title,
        "nodes": [
            {
                "id": keys[key],
                "key": key,
                "title": node.title,
                "kind": node.kind,
                "equations": node.equations,
                "note": node.note,
                "details": node.details,
                "explanation": node.explanation,
                "symbols": node.symbols,
                "normalization_equations": node.normalization_equations,
            }
            for key, node in diagram.nodes.items()
        ],
        "edges": [
            {
                "id": f"e{i}",
                "parent": keys[edge.parent],
                "child": keys[edge.child],
                "label": edge.label,
                "kind": edge.kind,
            }
            for i, edge in enumerate(diagram.edges)
        ],
        "policy": diagram.policy,
    }
    data = json.dumps(
        json_ready(payload), ensure_ascii=False, allow_nan=False, default=str
    )
    # A </script> inside a YAML string must never terminate the JSON element.
    for character, replacement in (
        ("<", r"\u003c"),
        (">", r"\u003e"),
        ("&", r"\u0026"),
    ):
        data = data.replace(character, replacement)
    assets = Path(__file__).with_name("graph_viewer")
    mathjax = assets / "vendor" / "mathjax-3.2.2"
    values = {
        "TITLE": escape(title),
        "DATA": data,
        "STYLES": (assets / "viewer.css").read_text(encoding="utf-8"),
        "SCRIPT": inline_javascript(
            "\n".join(
                (assets / filename).read_text(encoding="utf-8")
                for filename in (
                    "hybrid_layout.js",
                    "model_layout.js",
                    "hybrid_routes.js",
                    "force_layout.js",
                    "viewer.js",
                )
            )
        ),
        "MATHJAX": inline_javascript(
            (mathjax / "tex-svg-full.js").read_text(encoding="utf-8")
        ),
        "SAFE_COMPONENT": inline_javascript(
            (mathjax / "safe.js").read_text(encoding="utf-8")
        ),
        "MATHJAX_LICENSE": escape((mathjax / "LICENSE").read_text(encoding="utf-8")),
    }
    template = (assets / "viewer.html").read_text(encoding="utf-8")
    # Single-pass replacement does not interpret token-like strings in YAML.
    pattern = (
        r"@@(TITLE|DATA|MATHJAX_LICENSE)@@|"
        r"/\*\s*BUNDLED_VIEWER_(STYLES|SCRIPT|MATHJAX|SAFE_COMPONENT)\s*\*/"
    )
    return re.sub(pattern, lambda match: values[match[1] or match[2]], template)

