def test_coverage_observations_are_genderless_t_values(
    panel: demo.Panel, raw: pd.DataFrame
) -> None:
    for code, arr, center in (
        (demo._COV_3G_CODE, panel.cov_3g, panel.cov_3g_center),
        (demo._COV_4G_CODE, panel.cov_4g, panel.cov_4g_center),
    ):
        assert arr.shape == (panel.n_countries,)
        expected = np.array(
            [_ttt_value(raw, code, c, source=demo._COV_SOURCE) / 100.0 for c in panel.countries]
        )
        np.testing.assert_allclose(arr, expected)
        # Coverage lands on [0, 1] after the /100 -- not still on a percent scale.
        assert arr.max() <= 1.0
        # The frozen standardization center is the raw mean of this very sample.
        assert center == pytest.approx(float(expected.mean()))

