def _per_node_graph() -> BayesGraph:
    g = BayesGraph()
    g.add_node(
        NodeMeta(
            node_id="theta_a",
            kind="parameter",
            cpd_spec=CpdSpec(
                family="normal",
                constructor="prior_v0",
                hyperparameters={
                    "axes": (_COUNTRY,),
                    "loc": _LOC_A,
                    "scale": _SCALE,
                },
            ),
        )
    )
    g.add_node(
        NodeMeta(
            node_id="theta_b",
            kind="parameter",
            cpd_spec=CpdSpec(
                family="normal",
                constructor="prior_v0",
                hyperparameters={
                    "axes": (_GENDER,),
                    "loc": _LOC_B,
                    "scale": _SCALE,
                },
            ),
        )
    )
    for nid, parent in (("node_a", "theta_a"), ("node_b", "theta_b")):
        g.add_node(
            NodeMeta(
                node_id=nid,
                kind="passthrough",
                cpd_spec=CpdSpec(
                    family="testutil",
                    constructor="passthrough",
                    parameter_bindings={"param": (parent,)},
                ),
            )
        )
        g.add_edge(parent, nid)
    return g

