def test_root_latent_classification(_pipeline_registry) -> None:
    # M4's ``normal.bundled`` (shape via ``entries`` + a ``scale`` parent) is
    # not on this branch; the exact-set assertion is what excludes it -- and
    # any other non-root -- once it lands.
    roots = {
        (family, ctor)
        for family in REGISTRY
        for ctor in REGISTRY[family]
        if is_root_latent_constructor(REGISTRY[family][ctor])
    }
    assert roots == {
        ("beta", "prior"),
        ("beta", "prior_v0"),
        ("lognormal", "prior_v0"),
        ("normal", "prior_v0"),
    }

