def test_mean_coeffs_bundle_rides_the_scoped_axis() -> None:
    cfg = desugar(
        _cfg(
            [_truncated("mob"), _plain("income")],
            edges=[["income", "mob"]],
        )
    )
    # mean_coeffs is auto-built as an effect-group bundle; with no disaggregation
