def test_non_complement_roles_left_untouched(_pipeline_registry) -> None:
    """3. Roles outside ``COMPLEMENT_ROLES`` never get a baked ``axes``.

    ``prior_v0``, ``standardization``, ``structural_prereq``, ``observation_v0``,
    and ``constraint_v0`` all keep whatever shape they already declare (here,
    none): the pass must not write an ``axes`` hyperparameter for them.
    """
    non_complement = {
        "prior": ("normal", "prior_v0"),
        "stdz": ("standardize", "zscore"),
        "prereq": ("transition_logits", "linear"),
        "obs0": ("beta", "observation_v0"),
        "constr": ("bernoulli", "constraint_v0"),
    }
    nodes = [
        {"id": nid, "cpd": {"family": fam, "constructor": ctor}}
        for nid, (fam, ctor) in non_complement.items()
    ]
    for nid in non_complement:
        assert _baked_axes(nid, nodes) is None, nid

def test_exclude_axes_drops_a_complement_axis(_pipeline_registry) -> None:
    """4. ``exclude_axes`` subtracts a demographic axis from the complement.

    The v0 motivating case: cov_3g/cov_4g are indicator latents that exclude
    ``gender``. What remains is the complement minus the excluded axis.
    """
    axes = _baked_axes(
        "ind",
        [
            {
                "id": "ind",
                "cpd": {"family": "manifestation", "constructor": "mixture_mean"},
                "exclude_axes": ["gender"],
            }
        ],
    )
    assert axes == ["country"]

def test_include_axes_augments_the_complement(_pipeline_registry) -> None:
    """6. ``include_axes`` *adds on top of* the complement (does not replace).

    The ratified M3b semantics: an included axis is appended after the full
    demographic complement, which stays present in its entirety.
    """
    axes = _baked_axes(
        "ind",
        [
            {
                "id": "ind",
                "cpd": {"family": "manifestation", "constructor": "mixture_mean"},
                "include_axes": ["segment"],
            }
        ],
    )
    assert axes == ["gender", "country", "segment"]

def test_excluding_a_demanded_axis_errors(_pipeline_registry) -> None:
    """7. Excluding a *structural* (demanded) axis is an error.

    A ``segment`` node demands its anchor's ``segment`` axis; asking to drop it
    via ``exclude_axes`` is a contradiction, not a deviation.
    """
    with pytest.raises(ValueError, match=r"node 'seg'.*demands structurally"):
        _baked_axes(
            "seg",
            [
                {
                    "id": "seg",
                    "cpd": {"family": "dirichlet", "constructor": "segment_v0"},
                    "exclude_axes": ["segment"],
                }
            ],
        )

