    """Item 6's converse, on the ``NodeDef`` surface rather than a ``priors`` block.

    Bundling is not effect-group-only and not auto-construction-only: any two
    nodes bundle by agreeing on ``bundle_id``, which is why it lives on the node
    block beside ``id``.

    The bundled pair are ``normal.prior_v0`` rather than the ``beta.prior`` of
    ``_latent``: ``beta.prior`` declares no ``site_fn``, so it is not bundlable
    and the bundlability check now refuses it. It passed here before only because
    that check silently skipped nodes it could not resolve -- the bug this test's
    subject change records.
    """

    def _bundlable(node_id: str, **kw) -> dict:
        return {
