def test_fan_out_over_a_count_keys_by_index() -> None:
    """Item 32b. ``over_count`` fans out n children carrying no extra axis.

    The AR(p) shape: the criterion is not "number of axes", and the keys need not
    be axis names. Same addressing surface -- ``priors.coeffs.2`` steers the
    second child -- because a key is a key.
    """
    out = desugar(
        _cfg(
            [
                {
                    "id": "ar",
                    "kind": "latent",
                    "cpd": {
                        "family": "f_lags",
                        "constructor": "v0",
                        "hyperparameters": {"order": 3},
                        "priors": {
                            "coeffs": {"2": {"cpd": {"hyperparameters": {"scale": 7.0}}}}
                        },
                    },
                }
            ]
        )
    )
    assert _get(out, "ar").cpd.parameter_bindings["coeffs"] == [
        "ar_coeffs_1",
        "ar_coeffs_2",
        "ar_coeffs_3",
    ]
    # An index is not an axis: under `over_count` the key names the child and
    # addresses it, but contributes nothing to its shape.
    assert _get(out, "ar_coeffs_1").cpd.hyperparameters["axes"] == []
    assert _get(out, "ar_coeffs_2").cpd.hyperparameters["scale"] == 7.0
    assert _get(out, "ar_coeffs_1").cpd.hyperparameters["scale"] == 1.0

