def test_bundling_emits_one_site_where_solo_realization_emits_several():
    specs = (_spec("a", _axes(("x", 2))), _spec("b", _axes(("y", 3))))
    _, bundled_tr = _draw(
        lambda: bundle_sites(specs, sample_fn=_sample_fn, name="theta")
    )
    assert [k for k, v in bundled_tr.items() if v["type"] == "sample"] == ["theta"]

    def solo():
        return tuple(
            realize_site(s, sample_fn=_sample_fn, name=n)
            for s, n in zip(specs, ("a", "b"))
        )

    _, solo_tr = _draw(solo)
    assert [k for k, v in solo_tr.items() if v["type"] == "sample"] == ["a", "b"]

