def _truncated_build(**params):
    # The family that defeats reading bundlability off a built distribution:
    # `dist.TruncatedNormal` is a factory whose product cannot be reconstructed
    # from its own `arg_constraints`. Only the CPD knows how to call it -- which
    # is exactly what `SiteSpec.build` carries.
    return dist.TruncatedNormal(**params)

