def _target(n_years: int = _N_YEARS, *, axes: tuple[str, ...] = ("country", "year")):
    """A `p*` field on `axes`, with distinct values in every cell.

    Distinctness matters: it is what makes "the loc equals the target" a real
    assertion rather than one that a transposed or broadcast array would also
    satisfy.
    """
    sizes = {"country": _N_COUNTRIES, "year": n_years, "sex": 2}
    shape = tuple(sizes[a] for a in axes)
    kinds = {"country": "categorical", "year": "ordinal", "sex": "categorical"}
    return StructuredArray(
        array=jnp.linspace(0.1, 0.9, int(jnp.prod(jnp.array(shape)))).reshape(shape),
        axes=tuple(
            AxisMeta(name=a, levels=tuple(range(sizes[a])), kind=kinds[a])
            for a in axes
        ),
        indicator=IndicatorMeta(indicator="p_star", family="rate", unit="rate"),
        population=None,
    )

def sample_fn(name, distribution, step=None):
    del step
    return jnp.asarray(numpyro.sample(name, distribution))

def model():
    captured.append(
