    return transition_logits_linear(
        {"biases": (biases,), "weights": (weights,), "drivers": tuple(drivers)},
        sample_fn=None,
        deterministic_fn=_RETURN_VALUE,
        hyperparameters=hyper,
        name="transition_logits",
    )

def _expected(a, g, driver_values_by_name, driver_levels=_DRIVERS) -> np.ndarray:
    """Reference: logit[c, t] = a[t] + sum_d x_d[c] * g[t, d]."""
    x = np.stack([driver_values_by_name[d] for d in driver_levels], axis=0)  # (D, C)
    return (g @ x).T + a  # (C, T)

def test_logit_equals_linear_combination() -> None:
    """logit_t = a_t + sum_j g_{t,j} x_j, hand-computed. Defends the form."""
    a = np.array([0.5, -1.0, 0.2])
    g = np.array(
        [
            [1.0, 0.0, 0.0],   # t1 loads on dispinc_pc
            [0.5, 0.3, 0.0],   # t2 on income + cov_3g
            [0.2, 0.0, 0.8],   # t3 on income + cov_4g
        ]
    )
    vals = {
        "dispinc_pc": np.array([1.0, -2.0]),
        "cov_3g": np.array([0.5, 0.5]),
        "cov_4g": np.array([2.0, -1.0]),
    }
    out = _call(
        _biases(a),
        _weights(g),
        [_driver(n, vals[n]) for n in _DRIVERS],
    )
    np.testing.assert_allclose(
        np.asarray(out.array), _expected(a, g, vals), atol=1e-6
    )

