def _expected_gg(a, g, vals_full, driver_levels=_DRIVERS) -> np.ndarray:
    """Reference for two disaggregation axes.

    ``a``: (G, U, T); ``g``: (G, U, T, D); ``vals_full[d]``: (C, G, U) -- each
    driver already broadcast to the full grid. Returns (C, G, U, T).
    """
    n_c = next(iter(vals_full.values())).shape[0]
    n_g, n_u, n_t = len(_GENDERS), len(_URBAN), len(_TRANSITIONS)
    out = np.zeros((n_c, n_g, n_u, n_t))
    for c in range(n_c):
        for gi in range(n_g):
            for ui in range(n_u):
                for t in range(n_t):
                    acc = a[gi, ui, t]
                    for di, d in enumerate(driver_levels):
                        acc += vals_full[d][c, gi, ui] * g[gi, ui, t, di]
                    out[c, gi, ui, t] = acc
    return out

