def needs_marks(step: str, raises: type[BaseException]):
    """The same pin as ``needs``, as marks -- for one case of a parametrization.

    A parametrized test whose cases are blocked by *different* steps cannot wear
    a single decorator; ``pytest.param(..., marks=needs_marks(...))`` pins the
    one case without claiming anything about its siblings.
    """
    if not _STEP.match(step):
        raise ValueError(
            f"{step!r} is not a plan step id; expected a rev. 9 phase letter "
            f"from {_PHASES!r} with an optional item suffix, e.g. 'B1' or 'A1b'"
        )
    return (
        pytest.mark.needs(step),
        pytest.mark.xfail(
            strict=True,
            raises=raises,
            reason=(
                f"pinned to plan step {step}: expects {raises.__name__} until then"
            ),
        ),
    )

def test_a_pin_records_its_step_and_expected_error() -> None:
    """The two arguments must both reach the marks, or the pin proves nothing."""
    @needs("B1", ValueError)
    def sample() -> None: ...

    by_name = {m.name: m for m in sample.pytestmark}
    assert by_name["needs"].args == ("B1",)
    xfail = by_name["xfail"]
    assert xfail.kwargs["strict"] is True
    assert xfail.kwargs["raises"] is ValueError
    assert "B1" in xfail.kwargs["reason"]

def test_item_suffixes_that_the_plans_actually_use_are_accepted() -> None:
    """``A1b`` is a real step; a bare letter is a whole phase, also legitimate."""
    for step in ("A", "A1b", "B7", "I1", "H4"):
        assert needs(step, ValueError) is not None
